insert into public.chunks (id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length)
select id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length
from jsonb_to_recordset($jsonpayload$
[{"id": "4f7d2c1a-e3a6-4402-a006-a247250a345e", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 13, "content": "Kris Hampton (29:09): And I think we also have to allow that to shift. My goal with Power Company climbing originally was to build this business that could be sustainable while helping other people become better climbers. And I've done that to a level that I'm happy with. I could have continued trying to build it. Let's grow bigger, bigger, bigger, bigger, because that's what we're supposed to do. That's what we've always heard. But once I realized, oh, I've reached my goal here, I'm happy with where this business is, and it's at a place where passively I can mostly passively, I can let it run. (30:05): And then I asked myself, what do I want to do now? And because I'm like, I was waking up thinking about the podcast and thinking about who can I interview and how many can I fit in this month? And I thought, wow, let's change the goal a little bit. I'll keep some attention over here on power company climbing, and I'll make sure that I'm not forgetting about my clients, but I also want to start telling better stories, more important stories. And so now my goals have shifted. I think that's an important thing as well. Notice when you've reached your goal and you don't have to keep hammering on it, and then you can set other goals if that's what you're psyched to do.\n\nCole Heilborn (30:50): Was that tough to not continue to press the gas pedal a hundred percent on the coaching business? I mean, you could have kept going bigger and better, right?", "token_estimate": 367, "speakers": ["Kris Hampton", "Cole Heilborn"], "start_timestamp": "29:09", "end_timestamp": "30:50", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "4f5a9c2a-97db-4dbb-937e-0b826e448cbb", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 14, "content": "Kris Hampton (31:01): Yeah. I see some other training businesses doing something similar where it's like, how can we get more people in the door? And I could have gone that route, that could have become my focus. So it was hard. Here I am building this business as one of the first people in the industry to do it, and now there are other businesses that are growing bigger in different directions, and I could have easily gone that same direction had I let myself get trapped in the idea of I need to grow a bigger business. But the goal was to put a quality product out there to help people become better climbers. And I realized that one-on-one coaching isn't the most effective way to do that, and I'm doing it far more effectively through telling stories. So ultimately I'm still attacking that original goal by sort of shifting the goal, if that makes any sense. But yeah, definitely hard to do reassess and question my assumptions.\n\nCole Heilborn (32:17): So I'm noticing some interesting parallels, and I'm curious if this sticks for you or if I'm just way off here. So at the beginning of this conversation, you mentioned that one of the reasons why you really enjoy the coaching is that you get to help climbers build confidence and help them realize their confidence. I'm also noticing that there's a lot of things, maybe a lot of messages or philosophies that we're told in business or in the world of podcasting that we have to be doing or we should be doing. And it sounds like you're very confident knowing what you want to do and knowing what you don't want to do and not being swayed by whatever the latest trend or the latest fad is. I'm curious if there's a connection between your own confidence when it comes to climbing and how you choose to run your business and how you make decisions about how to run your business.", "token_estimate": 460, "speakers": ["Kris Hampton", "Cole Heilborn"], "start_timestamp": "31:01", "end_timestamp": "32:17", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "70c97ef6-8c21-4a4e-985d-1b3ee7f5bae7", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 15, "content": "Kris Hampton (33:10): For sure. I think it's all tied together. I think anytime we approach our lives as this holistic thing that's not just in a bunch of separate buckets all the time, it does all get tied together. So yes, the lessons I'm learning in climbing, I carry over to business and to life, and the lessons I'm learning in business, I carry over to climbing and to life, and all those things work together for sure. And I hope that's what I impart to the people that I work with in either capacity, whether it's climbing or in the podcasting world old. I hope that's what they get from it as well, that all this can be tied together exactly how I did when I was rapping about climbing way back.\n\nCole Heilborn (34:06): Changing gears a little bit here. I'm curious, how do you grow your podcast? How do you market your podcast? Are there specific ways that you have found to do that that works well?", "token_estimate": 228, "speakers": ["Kris Hampton", "Cole Heilborn"], "start_timestamp": "33:10", "end_timestamp": "34:06", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "fad170d0-2bd0-40e8-8c8f-8d34c0f8e707", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 16, "content": "Kris Hampton (34:19): Yeah. I don't know that I'm very good at this. I try lots of things. Like I said, I do think if we're just looking for nuts and bolts, ways to grow these things, having guests on who really believe in the mission and who aren't just a self-serving guest who's like, oh, I did this thing. I want to tell people about it. But if they really believe in what you are doing, they're far more likely to tell everyone else about it too. So I think getting guests who share your vision and share your mission is really important. For me, honestly, the big name guests haven't been as important. I can have the top climbers on my podcast, but they don't mean as much to me. They don't bring as many people in as some of the people who most climbers have never heard of, but they also share this mission, share this vision, and they're willing to tell everybody they know about it. So I think that's a really important and maybe counterintuitive thing. (35:38): Also, I think consistency goes so far, and I think a lot of people will bail when it doesn't seem to be working after the first four or five or even 10 episodes. And it really took off for me after I had 30, 40, 50 episodes. That's when it really started to grow. And I treat my audience like my friends essentially. I think that's a great way to market your product. I really believe in this hundred true fans or thousand true fans idea where I'm not terribly interested in putting my podcast in front of a million people. I would much rather really tell the stories that my thousand true fans really want to hear, because I know those true fans are going to tell all of their friends who also share this same vision. So I think for me, those things are far more important than How good is your Instagram reel or are you putting it on Twitter or TikTok?\n\nCole Heilborn (36:54): Yeah. What's your take on social media and how it plays a role in your podcast? There's always a new tool to be using.", "token_estimate": 493, "speakers": ["Kris Hampton", "Cole Heilborn"], "start_timestamp": "34:19", "end_timestamp": "36:54", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "adeb8af5-662b-4115-95e0-29835e241a11", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 17, "content": "Kris Hampton (37:02): Yeah, it's so tricky. I love social media. I really do. I think it like anything else, it's got its upsides and its downsides. The one thing I will say is I think it's easier to fall victim to the downsides as social media proliferates everything we do. And because new tools are constantly coming out, it's hard to keep up with. It's hard to create a quality social media post when it's like, oh, I have to make it for YouTube. I have to have it on Twitter. I have to make a TikTok, I have to have a reel. I need a post in my feed. And I'm sure there are 10 others that I'm missing here because I'm just too old to even understand. So I think it's a tricky place that you should approach with some skepticism, but I do think it's valuable, and I love the idea that I can put something out there that can resonate with someone else and they can immediately share it to their friends. And that's what I'm looking for. I don't give a damn how many people like it or how many people view it, as long as the true fans out there that it resonates with them and that they can then share it with their people.\n\nCole Heilborn (38:28): I feel like that's a bold statement to make. If you're not concerned about the response, you're not concerned about the likes. That seems so counterintuitive.", "token_estimate": 327, "speakers": ["Kris Hampton", "Cole Heilborn"], "start_timestamp": "37:02", "end_timestamp": "38:28", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "9c856504-da6f-4754-af9e-f70372d3edaa", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 18, "content": "Kris Hampton (38:38): It does, and I think it comes down to the fact that I can't control what that algorithm is, so I really just want to reach the people that I care about and that I know care about the thing that I'm making as opposed to being the next popular thing. I look into these things pretty heavily. Like I said, I love going down rabbit holes, and when reels were first becoming popular, I would look at other people's reels and think, Jesus, how did they, that's got 20,000 views? How is that even possible? And so I started looking into the algorithm and looking into what this data means. And at the time, what I found was that anytime a reel passes someone's screen, whether they watch it or not, it counted as a view. I've recently read that it has to be watched for three seconds now, which is maybe why there are lots of people saying, my reels aren't being the algorithms holding me down because they aren't being viewed like they were. Well, maybe they just changed what a view means. And so 20,000 times that it passes someone's screen is not important to me. I would rather have my a hundred people who are paying attention actually watch the thing and get something out of it. And that view count doesn't tell me if that's happening or not.\n\nCole Heilborn (40:13): Right. 20,000 views at three seconds. A piece doesn't account for much versus a hundred people listening to an hour long conversation.\n\nKris Hampton (40:22): Right? Totally. So keep the goal of goal. It's the goal is to have people listen, get something important out of it, not to gain more likes or more views.", "token_estimate": 401, "speakers": ["Kris Hampton", "Cole Heilborn"], "start_timestamp": "38:38", "end_timestamp": "40:22", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "1604af00-ea11-45bc-a7ff-c16cca772a4a", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 19, "content": "Cole Heilborn (40:36): So there's this book that I have read, and it's called Zig Wait, Zig Then Zag or Zig or Zag, I can't remember. It's sitting on the bookshelf behind me, the premise. It's a branding book and it's all about how to position yourself, how to think about where you sit in the marketplace. It's a really great book. I highly recommend it, but the entire idea is that when everyone is zigging, you should be zagging, basically do the opposite of what everyone else is doing. And I feel like, I think I've said this before, but Warren Buffet always says, do the opposite of what everyone else is doing. If everyone's buying, then you should be selling vice versa. And that might be too simplistic of a view on some of these matters. But I'm curious now that podcasting has become the thing to do, should we all stop podcasting and find the next thing?\n\nKris Hampton (41:32): I wish everyone else would stop podcasting because I'd be the only one left. But no, I don't think so. I think we just reexamine our assumptions about what podcasting means. For me personally, I'm leaning away from the Straight Up Interview podcast and more into how can I use sound design and music and narration to tell better stories. It doesn't mean I don't love the interview podcast, I still do, but I'm exploring all these other things because now there are, I mean, millions of interview podcasts out there and what's going to make mine special. I've spent a lot of time trying to be a better interviewer and trying to keep this conversation moving in a natural way. And I think I've maxed that out for myself, so I'm going in other directions. So I don't know if it's always a full on Zig when everyone else is zagging, but I do think that's a good idea to think about where can I go next? Everyone else has gotten to my level, where can I go? That's interesting and unique.\n\nCole Heilborn (42:53): Can you share more about where you're hoping to go? You mentioned that you're trying to do more narrative or story-based podcasts. Is that the next thing on your horizon?", "token_estimate": 517, "speakers": ["Cole Heilborn", "Kris Hampton"], "start_timestamp": "40:36", "end_timestamp": "42:53", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "3c60bf72-d32f-47a2-8283-3c6833284b1c", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 20, "content": "Kris Hampton (43:05): Yeah, that's what I'm working on. That's what I'm working on right now. And I've leaned into it a little bit with Hip hop Taught me everything. And the Built Outdoors series that we've just started is very much a sound rich sound designed and highly edited and produced podcasts that's very inspired by things like Radio Lab and this American Life and radio in general. I think we've almost taken this reductionist approach to podcasting where it started with these highly produced, this American life that was the big one for a lot of years. And we've gotten away from that in a reductionist sort of way, a minimalist sort of way, which I really love, and I think is a necessary evolution, so to speak. It seems like a backwards, a devolution, I guess, but I do think it's a necessary thing to really boil something down to its individual parts and then you can build it back up. So now that I've become what I think is a good interviewer, I want to expand that and be able to color those interviews with music and with sound and really weave a good story together as opposed to just a good conversation. So on our plug Tone Outdoors channel, I'm experimenting with a lot of that, and that's where I put out the cowboy poem you mentioned, and I'm just really making some art projects that I'm putting out there and seeing what sticks.\n\nCole Heilborn (44:56): What's your take on video podcasting? YouTube has obviously been pushing that pretty hard. I don't know much about it, but it sounds like Spotify also is making that part of their offering now. What role does that play in the future of podcasting?", "token_estimate": 408, "speakers": ["Kris Hampton", "Cole Heilborn"], "start_timestamp": "43:05", "end_timestamp": "44:56", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "274093ab-1ec3-41eb-b484-c7566212ad6d", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 21, "content": "Kris Hampton (45:12): I think it's probably big, and I don't think I know enough about it or haven't delved into it enough. I don't have a background in video editing, so maybe you and I need to team up on a video podcast. And at first I thought there's no reason for a video podcast where it's just talking heads and you're seeing people talk to each other. But then recently, oh, I can't think of the name of it. Recently, a new podcast hosted by Brandon Jenkins, who's a hip hop writer, came out and it's a video podcast that's, he talks to people, it's like a talk show in this beautiful set, and they have several cameras going, and it's released on Spotify as a video podcast. And I really wanted to listen to it, but I found myself watching the video even though it's just people talking. So I have to imagine that it's going to be a big part of the future, and I just don't know where it's going yet. I would love to see there are some reels out there that are sort of acting out what's being talked about in the podcast or animated versions of what's being talked about, and I would love to see whole stories done that way. I know that's a lot of work, but I suspect it's coming.\n\nCole Heilborn (46:45): That would be wild. That would be so cool. I guess this is a question for the audience. If anyone feels like responding or curious, I mean, I'm looking at Chris right now. He's looking at me instead of just hearing our voices. Would you prefer to see our faces while we're chatting? I don't know. It's an interesting question, but I find myself, if the content is good enough, I would much rather watch a video. I feel like I'm picking up more on those minor social cues from the host or the guest.", "token_estimate": 428, "speakers": ["Kris Hampton", "Cole Heilborn"], "start_timestamp": "45:12", "end_timestamp": "46:45", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "f8990d0d-5c6b-4d6a-add1-7f9816366deb", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 22, "content": "Kris Hampton (47:15): And there's definitely something there with the, like I said, I treat my audience like my friends, and it's very much like I'll meet someone at the Crag just this past weekend at the Joes Valley Climbing Festival, I was talking to someone and they're like, wait a minute. I know your voice. You're this guy. And that happens a lot. And I'll have people recognize my voice and then say, oh, how did that project go that I heard you talk about last week? But there's definitely something to seeing someone's face that makes you feel like you know them in some way. And I do think that's a really important aspect of this true fans theory is bringing them into your world a little bit, and maybe video does a better job of that.\n\nCole Heilborn (48:06): Well, I almost wonder, this just hit me, I think about pre COVID, how conferences and going to conferences, thought leadership events, meetings were super popular. And there was a couple that I went to, but it was always such a fun environment where I'm, I'm never going to talk to the person on stage, but I'm there in the audience and I'm watching that person up on stage. And I feel like I have some similar connection to that individual. And I wonder if this is just the next form or another form of that same type of experience. If this was in a video format,\n\nKris Hampton (48:40): Yeah, it could be. What you just said led me to thinking about pre COVID. Anytime I was talking to a client, it was pretty much just on the phone. Very rarely did I use Skype or whatever video platforms were available out there. But since they've been improved, I much prefer to get on a video call with someone. I like the idea of being able to see people's faces and see their mannerisms and see their reactions. It's just a nicer experience. So I think I'm talking myself into a video podcast here.\n\nCole Heilborn (49:21): Maybe we need to start one. If you want to add another one to your quiver of podcasts.\n\nKris Hampton (49:27): Cole, I want to add 15 or 20 more into my quiver. Like I said, it's totally an addiction.", "token_estimate": 522, "speakers": ["Kris Hampton", "Cole Heilborn"], "start_timestamp": "47:15", "end_timestamp": "49:27", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "3465ad03-762b-4b6d-a0de-596a8dc7fa0c", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 23, "content": "Cole Heilborn (49:35): I'm honestly just impressed the fact that you want to continue to keep creating that mini, I mean, I guess I can relate. I always have this drive of wanting to create another film or another project and continue to push the creative boundaries or push myself. So I guess it's in a similar vein, but I don't know if I get as fired up as you do about podcasting. I think I probably get fired up a similar amount about video or film.\n\nKris Hampton (50:03): And you found that thing that fires you up so important. Something you asked a little earlier, it's sort of all coming back around now. When I'm coaching climbers, one of the most important parts of coaching them is modeling my coaching philosophies for them. Not just telling them, but acting it out, making mistakes myself, exploring myself. And I think that's a big part of what I'm doing with podcasts is this constant desire to grow and to learn and to try new things and to fail at things, to put things out there into the public that's just an art project that no one else likes but me, I'm totally okay doing that because it's modeling what I want people to get out of it all. And that's this willingness to explore the things that they're excited about.\n\nCole Heilborn (51:12): Is it possible, coming back to this idea of focus, is it possible for you to take that philosophy and make that philosophy your focus? I think sometimes we think of focus as being, I'm going to focus on hitting this sales goal for the year, but what if you could focus on an idea rather than an outcome? Is that harder to do?\n\nKris Hampton (51:33): I do think it's harder to do, but I think that's the essence of the goal is to keep the goal, the goal, really boil it down to your, why am I doing this? Why do I want to do this? Why am I excited about it? And keep that thing as your goal, as your focus. So for me, my focus is never, I want to get more listeners to my podcast. I want to make a specific thing. I want to make a better podcast. I want to be this philosophy that I keep preaching.", "token_estimate": 515, "speakers": ["Cole Heilborn", "Kris Hampton"], "start_timestamp": "49:35", "end_timestamp": "51:33", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "ec27c883-4c62-4d87-9f82-bf5789c5254a", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 24, "content": "Cole Heilborn (52:11): There was an interview with, I believe it was Bill Gates, I don't remember how long ago, but he was asked if you could have, there's any attribute or any skill that you could be better at, what would it be? And if I think about that question, there's a lot of things that I wish I was better at, but his answer was, I wish that I had more focus. And I feel like coming from someone of that caliber, it hits me in a different way thinking, well, bill Gates wishes he had more focus. I feel like if anyone has focus, it's someone like him, but I wonder what's truly possible if we're able to focus entirely on what we should be focusing on. And I think there's a difference there, and this gets back to that keep the goal of the goal idea, but if you could truly find what we need to all be focusing on and then just drive towards that, I wonder what the outcome could be.\n\nKris Hampton (53:10): Yeah, I think it will certainly make it easier to avoid the pitfalls of social media and the doubts that come along with putting something out there that no one is listening to or paying attention to so that you can continue trying. We've heard so many stories from artists, from writers, from athletes about, I wrote this thing and it got rejected a hundred times and then someone bought it and now it's a New York Times bestseller. We hear those stories constantly, and for every one of those stories, there are hundreds of people who got rejected once or twice and stopped submitting, didn't achieve their sports goal once or twice and stop trying to reach it. So I do think if we can find what it is, we should be focusing on whatever our goal is and we can keep that the goal. We avoid a lot of those pitfalls. I have to believe that, or I wouldn't be trying to do it myself.", "token_estimate": 450, "speakers": ["Cole Heilborn", "Kris Hampton"], "start_timestamp": "52:11", "end_timestamp": "53:10", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "6a9d6e6e-884c-401e-8892-081cd7628cf6", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 25, "content": "Cole Heilborn (54:26): So as you were just speaking there, I'm thinking about a camera lens and how it focuses and to the eye. When you're focused on a subject, it looks like it. Certain range of that depth is within focus, but in reality, only one point on that z axis is actually in focus. Everything else is slightly off. And the farther you get from that focus point, it becomes more softer and softer. And I'm thinking about what are the things that we think we need to focus on versus the things that we really need to focus on? And I'm picturing this camera lens analogy where there's a lot of things that are just slightly out of focus or are kind of soft, but we think are things that we need to be focusing on. But in reality, there's only, we can only focus on one thing. I guess that's my question. Can we only focus on one thing or one point at a time, or can we be focusing on a variety of things?\n\nKris Hampton (55:26): Well, I love that analogy. I think priority is a singular thing. I don't think there's a such thing as priorities, and I sort of feel that way about focus as well. I think you can move your focus around just like you can with a camera lens, but at any given time, your focus should be on one thing, and you absolutely should have other things that are in soft focus that are in the background, that are simmering because you're going to burn out if you're focused only on one thing forever. So I think it's a singular, I don't think you have many things in focus. I think you focus on the one thing while these other things are soft and you can move that focus to tell whatever story it is you want to, just like you would with a camera. If you're pulling focus to tell a story in a certain way, I think we can do the same thing in our lives.\n\nCole Heilborn (56:35): Well, you've given me a lot more to think about. This has been an insightful conversation.\n\nKris Hampton (56:40): Me too. I love working my way through this stuff and I love having conversations where the person I'm talking to is willing to work through these things instead of just having the click bait headline answer.", "token_estimate": 531, "speakers": ["Cole Heilborn", "Kris Hampton"], "start_timestamp": "54:26", "end_timestamp": "56:40", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "e9714f50-4c02-464a-b024-e966d098f59d", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 26, "content": "Cole Heilborn (56:58): I'm looking at the questions that I originally had teed up for this, and I don't think I've asked half of them, but I'm okay with that because I think the goal for me always from this podcast is just to find interesting people, have an interesting conversation and see where it leads. And so I feel like we have fulfilled my focus, at least with this podcast.\n\nKris Hampton (57:19): Alright, we did it. And that's how my podcasts always end up is I come up with a few questions and I never get around to them.\n\nCole Heilborn (57:27): Chris, we're unfortunately coming to the end of our time for today. Is there anything that you want to wrap up? Any last thoughts that you want to leave with our audience?\n\nKris Hampton (57:37): I think based on this conversation we just had, I think it's explore. There are no absolute right answers. Just explore what works best for you and if you can understand your why and make that the goal and keep that the goal, then I think you go far.\n\nCole Heilborn (58:01): Well said. If folks want to follow along on any of the socials, where can they go to connect?\n\nKris Hampton (58:07): We are power company climbing.com on the interwebs and then at Power Company climbing on most everything. We also, our podcast network, which is a diverse group of really great impactful podcasts in the outdoor industry is plug tone audio.com. And we're plugged Tone audio on Instagram as well. And we've just started a new podcast channel Plug Tone Outdoors, which houses a lot of these art projects that we're talking about, including Built Outdoors, the Outdoor Entrepreneur podcast that your audience might really be interested in.\n\nCole Heilborn (58:49): Awesome. I thought of another idea for a podcast, one of your 20, you want to start? It should be called The Rabbit Hole. And maybe that exists already, but it seems like you'd be the type of person who could make it thrive.\n\nKris Hampton (59:01): Yeah, I've thought about this sort of idea a lot and I would love it.\n\nCole Heilborn (59:07): Well, Chris,\n\nKris Hampton (59:08): We'll make it a video podcast, Cole.", "token_estimate": 530, "speakers": ["Cole Heilborn", "Kris Hampton"], "start_timestamp": "56:58", "end_timestamp": "59:08", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "5b1f663d-9866-47ed-85d8-caeb242c333c", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 27, "content": "Cole Heilborn (59:10): It sounds good. And we'll do nothing but wander down the rabbit hole and see where it takes us. Well, Chris, thanks again for taking the time today. I hope you have a great rest of your day, and I'm looking forward to connecting in the future and seeing what podcasts you've fired up again.\n\nKris Hampton (59:27): Yeah, thanks for having me, Cole. I really appreciate it. I love what you're doing and giving people lots of options for how they can be successful in this thing.\n\nCole Heilborn (59:38): I appreciate it. Have a great day.\n\nKris Hampton (59:40): You too.\n\nCole Heilborn (59:40): Bye. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 208, "speakers": ["Cole Heilborn", "Kris Hampton"], "start_timestamp": "59:10", "end_timestamp": "59:40", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "e1651c3b-ce70-4f61-9f50-95731d40b942", "episode_id": "7d754328-473d-4dfc-9a75-5e43416491ba", "cms_item_id": "68225dfc7bb476527f8c489e", "chunk_index": 0, "content": "David Meredith (00:00:02): I have to treat everything as if it is a CTE response because that is the number one thing that is causing a shelf life to me. If I'm not careful, I will not see my children graduate high school. I'm 47. There is a real possibility I won't see 50, I won't see 60, I won't see 70, and I need to live my life that way, but I need to live it in a positive way, not in a Hunter Thompson way.\n\nCole Heilborn (00:00:33): Welcome to the Backcountry Marketing Podcast. My name is Cole Hallborn and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer, I hope you enjoy today's episode. This is the Back Country Marketing Podcast Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest.\n\nDavid Meredith (00:01:06): Welcome to the Backcountry Marketing Podcast. Today I'm sitting down with David Meredith. He is the Dirt marketing manager for FSA America. David, how are you?\n\nDavid Meredith (00:01:15): I'm doing quite well, sir. How about yourself?\n\nDavid Meredith (00:01:17): Doing very well. Yeah, on a nice crisp October fall day that's going to quickly turn into a hot day for us here in the northwest. That seems very out of place.\n\nDavid Meredith (00:01:29): Oh, man. Yeah, especially for October.\n\nDavid Meredith (00:01:33): Yeah, no kidding. Where are you calling in from?\n\nDavid Meredith (00:01:36): Buckle, teal, Washington. So not too far south of you?\n\nDavid Meredith (00:01:39): Yeah, just within an hour, which is unusual because I feel like most of our guests on this show, I'm at least in a different time zone, so I feel like we got that going for us. It's the same time. David, I'd love if you could give a quick introduction, quick background on FSA, what you guys do and what your role with the company is.", "token_estimate": 515, "speakers": ["David Meredith", "Cole Heilborn"], "start_timestamp": "00:00:02", "end_timestamp": "00:01:39", "podcast_index": 121, "episode_name": "EP 121: Mental Health and CTE in the Workplace | David Meredith | Full Speed Ahead", "slug": "ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "web_url": "https://www.portsidepro.com/podcast-feed/ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "guest_name": "David Meredith", "guest_title": null, "categories": [], "short_description": "David Meredith is the Dirt Marketing Manager for Full Speed Ahead and has been in the bike industry for years, including racing, owning a retail shop, and operating his own international bicycle brand. David comes on the show to share his experience in the bike industry, but also, to share his experience being a human pre-diagnosed with CTE, Stage 4. In this episode, David and Cole discuss:", "podcast_length": "1:15"}, {"id": "32d543b3-40e2-4aa6-a167-adc0ca7ce1fe", "episode_id": "7d754328-473d-4dfc-9a75-5e43416491ba", "cms_item_id": "68225dfc7bb476527f8c489e", "chunk_index": 1, "content": "David Meredith (00:02:00): Sure. Well, FSA, it is an acronym. It stands for Full Speed Ahead. We're a component company for bicycles. We are the third largest bicycle component company in the world. Next Tora and Shimano, we make everything including drivetrain for road bikes, hbar stems, wheels, headsets, most famous for our headsets. They seem to come on every single bike imaginable and whether you know it or not, because we tend to OEM and private label a lot of that stuff too. We've been around for the better part of 25 years, almost 30 years. The parent company industries is out of Taiwan, and then we have our European office, which is outside of Milan, Italy, and our US office is here in Muckle, teel, and we've been here in Muckle, teel for maybe 12 to 15 years. I forget. We started off in Woodenville, so we've always been northwest fresh, if you will, and the American office here is the seat for all things Mountain. So our Italian office handles road and road Engineering, and then we handle mountain and Mountain engineering as well as mountain marketing and product development.\n\nDavid Meredith (00:03:36): Got hence your title of dirt marketing.\n\nDavid Meredith (00:03:40): Exactly. So that covers all mountain bike, and then I do lots in the gravel and cyclocross markets as well.\n\nDavid Meredith (00:03:49): Gotcha. Okay. What do you personally enjoy riding these days? Are you taken to the gravel fad?\n\nDavid Meredith (00:03:58): Actually, I am. I've took that really hard because it reminds me of being in high school and the mountain bikes that we rode in high school back in the nineties and eighties and nineties. It's basically a gravel bike now with better wheels and better brakes. So it was exciting to do that. My first gravel bike was an OED boundary, and then I traded that in for a evil shammy Hagar, which got me into a lot of trouble because it rode like a mountain bike. So I was on legit downhill trails on that bike. But now I'm in the process of getting a custom built sage titanium, and I am really excited about that one because it's my geometry, so it's going to be fun.", "token_estimate": 530, "speakers": ["David Meredith"], "start_timestamp": "00:02:00", "end_timestamp": "00:03:58", "podcast_index": 121, "episode_name": "EP 121: Mental Health and CTE in the Workplace | David Meredith | Full Speed Ahead", "slug": "ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "web_url": "https://www.portsidepro.com/podcast-feed/ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "guest_name": "David Meredith", "guest_title": null, "categories": [], "short_description": "David Meredith is the Dirt Marketing Manager for Full Speed Ahead and has been in the bike industry for years, including racing, owning a retail shop, and operating his own international bicycle brand. David comes on the show to share his experience in the bike industry, but also, to share his experience being a human pre-diagnosed with CTE, Stage 4. In this episode, David and Cole discuss:", "podcast_length": "1:15"}, {"id": "f360452d-8849-4237-bcb1-fbed3f390b16", "episode_id": "7d754328-473d-4dfc-9a75-5e43416491ba", "cms_item_id": "68225dfc7bb476527f8c489e", "chunk_index": 2, "content": "David Meredith (00:04:51): So I know you have quite the history of being in and out of the industry. I'd love if you could kind of summarize your journey to where you are today. I know you started out racing, you at one point had started your own bike company. Could you kind of fill us in on some of the details?\n\nDavid Meredith (00:05:10): Sure, I'll try and keep it kind of brief. I tend to tell long round about stories. Let's see. I kind of got bit by the bug in high school in the early nineties. So I ran track and I was the third fastest one 10 high hurdler in California, and mountain biking was a cross training tool for running. But I got hit by a car and it took out my chances of going to the Olympics for running. And so I just dove into cycling because I could do that, and it didn't mess my knees up too much, and I had friends that were like, Hey, you need to start racing. Okay, cool. So I started racing and I was really good at it. So basically I raced cross country throughout all of California and high school. Moved to Colorado in 93 when I turned 18, upgraded to pro and then had my ass handed to me in the cross country races. So I picked up downhill racing and turned out I was really good at that. So I raced downhill from 93 until 2003 on the Nobo circuit and a couple of World Cup invitationals. (00:06:29): I raced for Yeti, I raced for intenses, a couple other private brands as a privateer, but for the most, and then for Turner Bikes started a team with him. But in 2002, I graduated from the University of Idaho and wanted to work more inside the industry. I had been kind of a sales rep outside kind of a guy, got a job working for Marzo as a OEM, sales and marketing for them, left them after I finished grad school. I was working with 'em while I was in grad school, finished them. Then kind of got back out of the bike industry and pursued my career in journalism. Worked for a newspaper back in Coeur d'Alene, Idaho, the Coeur d'Alene Press us while also kind of working for a group called the Superheroes, which was a mountain bike free ride media team. So we were making videos and I was doing sales and marketing for them for North America that got defunct after a while. (00:07:49): For whatever reason. I don't remember what happened. And I had met my wife, my then girlfriend, and she said, Hey, I'm moving to New Mexico. So I said, great. So we moved to New Mexico and I end up opening up a shop, which turned out to be the only downhill free ride bike shop in all of New Mexico, one of four of its kind. I think in the country. There was Speed Goat, there was Mojo Wheels, there was Fluid Ride, and I forget, there was another one somewhere. But our primary focus was downhill gravity, teaching classes, mechanic classes, writing classes, stuff like that. That evolved into a clothing line. The clothing line couldn't get enough funding that evolved into a bicycle line, which I know I'm truncating a lot of this, but I met a friend of mine who was the dyno test engineer for Harley Davidson, helped with the Vro project. (00:08:59): He basically connected the dots on the geometry charts that I was building for bikes. And he was like, Hey, I had another friend of mine whose son I was sponsoring with my shop who was a former triathlete and a mountain bike racer, and he said, Hey, let's make bikes. So we're like, oh, well, okay, bleep, let's make some bikes. So we dove into that. The bike brand was called One Ghost Industries named after my dog Ghost. I was the one, he was the ghost and the industries was the bike, and he was named after the Ghost Dog, which is the spiritual protector of the Samurai. That's a whole separate story. But Ghost was, he inspired me to start this. And so from 2006 till 2014, basically it was myself and my business partner, Rory. We designed, built, assembled, sold, marketed our own bikes using my suspension design, and we sold them all over the world. (00:10:10): And I had a World Cup team with one racer, art Babcock, who was, he still is, he races Baja 500 and Baja 100 now in the Ironman category. So in 2014, we shelved the brands. By 2014, we had multiple brands that we were running. We had one Ghost Industries, which was the mountain brand. We had stop cycles, sustainable transportation, zero pollution, which were basically what gravel bikes are now. So I was doing mountain bikes designed for drop bars, essentially. I called them Cross Mutters because they were for commuting, but they were Cyclo Cross and they were do everything, big, fat tire clearance, drop bars, all the fun stuff. And then I had a component group called Candy Components, which was handlebars stems, headsets, pedals. (00:11:14): So I sold off the IP for the component group and kept the IP for the two bike brands, shelved it, and went to work for Marzo again, a second time because I knew the product, I knew the brand, but this time they were owned by Tenneco. And so worked with them, brought them kind of back into the limelight, if you will, because by 2014 they were not necessarily as viable, but I was able to help bring them back up to online. I ran for them for North America and was able to get them to the point where Tenneco wanted to sell the brand. I brought them to the table for Shimano, for Fox, for a few other companies that were looking to buy them. As we know, Fox ended up purchasing them. When that purchase went through, everyone was going to get laid off, and I knew this, and they gave us six, eight months. (00:12:22): So I didn't wait around, but I ended up getting an offer to go and work for Crank Brothers. So I joined the team at Crank Brothers as their global sports marketing director and worked with them and from 2015 until 2017, and that was an amazing run. I have nothing but love for those guys. I had always used the pedals. I actually OEMed their product. But in 2016, we had our first son, Josiah, and my travel schedule was close to 200 days a year, global travel. So trying to do that with a newborn was just a non-start, and I had an hour and a half commute each way. I had to work in the office, didn't have provisions for working remotely, and so it was just mutually part of the way. So I was like, Hey, I can't do this anymore. They're like, okay, no worries. (00:13:33): So I left them, ended up working a little closer to home for specialized of all places, came on with them to help build out their retail stores. So I was the global service director for their retail chain. As you know, they now have specialized retail and they creating retail stores across the world. My job was to build out the service department in a way that it was kind of very Starbucks, if you will. So you go into the specialized in Glasgow, or you go into the specialized in Seattle or anywhere Nebraska. It'll be the exact same. You walk in there, the tools are going to be laid out the same, the service is going to be the same. You're going to get that top tier white shirt, Mercedes style service, what I wanted. And that's what we did. (00:14:43): So I did that for about a year and decided, Hey, this is just taking too much of my time still. I really want to spend these years with my son, the very important bonding years. When he was Little Ghost my dog, he was getting older. I really wanted to spend time with him. I had him since he was six months old, and he had literally been by my side the entire time for 14 years. So 2017 I left, or 2018 I left specialized to just be a stay-at-home dad, do freelance work, and took care of my son. My dog passed away at that time, which I was lucky enough to be able to be there with him and did that and went back to school actually in 2019 for nursing. And because I already had a master's degree, I already had an EMT certification, I was able to fast track my way into a master's of nursing. (00:15:59): So I started that, and then the pandemic rumblings were hitting in late 2019, beginning 2020, finished my semester in 2019, semester, started up in 2020 again, and started taking a really hard look at what was happening around the world and was like, I got a really bad feeling about this. So my wife and me were like, yeah, let's just ride this out and see what happens. And sure enough, the pandemic happened and life came to a halt for everybody, as we all know, by June, may I forget, maybe may I end up taking a job with InCycle Bicycles as their digital marketing director, taking on the role of helping them build and design their website and maintain an online presence because now everyone's switching to online. So creating an experience through their website, through digital integration and activations. So that was pretty fun. Took that on for a while, and then that got ugly for other reasons when the unrest started happening with the death of George Floyd, and there was some internal issues that I was like, I got to just leave. (00:17:29): So I started looking around, spoke to a friend of mine here at FSA, and he's like, Hey, let's see what happens. And then after a while, and this is now by 2021, I got an offer to come on board and was like, yeah, let's, heck yeah, let's take this. This is great. Worked remotely for a year for 2021, partly because the office here was closed only essential warehouse as needed. And then because I was in California at the time, so just worked remotely until just June of this year, we moved up here and we've been here ever since, and it's been great.", "token_estimate": 2369, "speakers": ["David Meredith"], "start_timestamp": "00:04:51", "end_timestamp": "00:05:10", "podcast_index": 121, "episode_name": "EP 121: Mental Health and CTE in the Workplace | David Meredith | Full Speed Ahead", "slug": "ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "web_url": "https://www.portsidepro.com/podcast-feed/ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "guest_name": "David Meredith", "guest_title": null, "categories": [], "short_description": "David Meredith is the Dirt Marketing Manager for Full Speed Ahead and has been in the bike industry for years, including racing, owning a retail shop, and operating his own international bicycle brand. David comes on the show to share his experience in the bike industry, but also, to share his experience being a human pre-diagnosed with CTE, Stage 4. In this episode, David and Cole discuss:", "podcast_length": "1:15"}, {"id": "b78fcbae-6791-4197-963d-016e9b0ec26f", "episode_id": "7d754328-473d-4dfc-9a75-5e43416491ba", "cms_item_id": "68225dfc7bb476527f8c489e", "chunk_index": 3, "content": "David Meredith (00:18:20): Wow. Yeah, that's quite the journey. There's a lot of stops in there. That sounded like a fun time.\n\nDavid Meredith (00:18:27): Yeah. The cool thing about all of that that I love going back to is Ghost. He was the greatest trail dog I've ever known. He rode trails in every single state from Colorado West, and he loved it. And this was before the days of smartphones, and I never had a GoPro. I never had any kind of camera to record any of it, and I'm really sad about that. But he would go on Epic rides with me. We'd go on 15, 20, 30 mile rides, and he just would not quit. And yeah, he was insane. He was amazing. So to this day, I've got my top cap of my bikes as I ride for ghost, and he was my rock through a lot of it.\n\nDavid Meredith (00:19:24): Wow. David, I'm curious if you could share with us when you were diagnosed with CTE.", "token_estimate": 217, "speakers": ["David Meredith"], "start_timestamp": "00:18:20", "end_timestamp": "00:19:24", "podcast_index": 121, "episode_name": "EP 121: Mental Health and CTE in the Workplace | David Meredith | Full Speed Ahead", "slug": "ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "web_url": "https://www.portsidepro.com/podcast-feed/ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "guest_name": "David Meredith", "guest_title": null, "categories": [], "short_description": "David Meredith is the Dirt Marketing Manager for Full Speed Ahead and has been in the bike industry for years, including racing, owning a retail shop, and operating his own international bicycle brand. David comes on the show to share his experience in the bike industry, but also, to share his experience being a human pre-diagnosed with CTE, Stage 4. In this episode, David and Cole discuss:", "podcast_length": "1:15"}, {"id": "4e8954dc-122b-4955-88d7-4268385f80da", "episode_id": "7d754328-473d-4dfc-9a75-5e43416491ba", "cms_item_id": "68225dfc7bb476527f8c489e", "chunk_index": 4, "content": "David Meredith (00:19:33): I can. That was when I was going to school for nursing. I was struggling with a lot of the work. Well, the chemistry itself, chemistry was always kind of hard, but this was, I kept having these weird, foggy brain, unable to think just strange, really irritable sensations. I hesitate to call 'em symptoms, but I went to my family doctor and I described all of these to her, and we started going down the rabbit hole of all of the TBIs that I've had. I've had over 14 knockout concussions where I've woken up and not known where I was through various accidents. One was a car accident where I was pulled from the car in seizures. Last thing I remember was seeing the car that hit me in the rear view mirror and then waking up in a hospital. I've had accidents on my bike where I've crashed and broken helmets. (00:20:52): I had had accidents, literally running through the house and tripping and hitting my head and waking up on the floor and pool of blood. So I've this history of hitting my head and very aggressive TBIs, well, CTE can't be officially diagnosed without a brain dissection, but through multiple brain scans and the knowledge that we have now of symptoms, she was confident enough to diagnose me with stage four CTE, which is exactly what it sounds like. And stage four is a shelf life. It's not a matter of if, it's a matter of when. And the, so I had to apply for specific student, I can't remember the name of it, but you apply for specific help from student services in terms of disability help. So it's student disability services, there's a name. And to do that, I have to get doctor's notes and things. So that was the rabbit hole that I went down. (00:22:28): And she went through all of this and I got the paperwork and the paperwork. I still have it said stage four CTE on the paperwork. And I spoke with her and we talked about it on the phone. We had a zoom meeting about it. And she said that she doesn't like being the person to make that diagnosis, but she was confident in speaking with the neurologist and with everything, the work that we had done, that that's on paper what it looks like. And we will never know until I'm dead, but we're going to approach my life as having that. So that meant a lot of changes, a lot of very paradigm shifts, if you will, in the way that I think and the way that I, and the things that I do physically, the things that I do mentally, the food that I intake, everything, including medication that I have to take. (00:23:59): And because a lot of what happens with CTE, which to those that don't know, CT E, chronic traumatic encephalitis or encephalopathy, I don't know how to pronounce the word. I get tongue tied on it, but it basically means your brain is dying from the inside out for lack of anything else. It's your brain is connected by a series of tissues. Every nook and cranny is connected by a series of tissues that are called tau proteins. And CTE is effectively a form of Alzheimer's in a way that the tau proteins that connect everything become brittle. Normally. They're loose. They're very fluid and flexible because as the electrical impulses that make the brain work come through these tau proteins and they flex and move, and as they become brittle, they will actually break and you'll lose connections within the brain. And that will then create neurological pathways to end. (00:25:18): So you can lose mental functions. And the majority of it happens in the frontal lobe. So in places of emotion and your ability to think, your ability to speak, but the biggest tell is your ability to self-regulate and anxiety, depression, hearing things, seeing things that aren't there. There's a list of various symptoms that have been recorded and later discovered based on individuals in both boxing and football who have passed away. And in BMX, including Dave Mira, and that was when Dave passed away. I believe that was 20 18, 20 17. I forget the exact year, but that really hit hard. It's like, oh, because I had kind of seen that pattern like, oh wow, it's not just depression or it might not just be depression. It might not just be anxiety. (00:26:52): There could be a lot else there. To be really frank about it, I have a history of abuse and trauma for my life. From the time I was little. I grew up in an incredibly abusive and neglectful household. So I have a lot of trauma and a lot of PTSD and a lot of complex PTSD from growing up. Now, CTE, well backtrack a little bit. TBIA traumatic brain injury creates PTSD, and that's a scientifically verified fact there. When TBI happens, the brain records it as post-traumatic stress disorder, and then the body holds onto that. Now, you can't have CTE without TBI from the science that I know of and the science that is read about because it's not Alzheimer's. Alzheimer's is its own creature. It's a oxidation of the tau proteins. It's similar but different enough. It's not caused by direct impact to the head where TBI is literally traumatic brain injury. (00:28:25): It's direct trauma to the head, which then causes CTE to happen. Now, CTE manifest itself as complex post-traumatic symptoms. So that's where it gets really complicated for me and for a lot of doctors to really be able to see it and diagnose it. You have to look at the entire picture and the overall history of who it is. Now, I was never really close with Dave, with Mira. I spoke with him on a number of occasions at different events, but the stories that I had heard third party of like, oh, wow, yeah, okay, yeah, you've hit your head a number of times. And the direction that he went was down that depression, anxiety, everything. The NFL players who have Oscar or ez, I think it's Oscar ez, who's the one who really stands out in my mind. I don't follow football at all, but that's where the majority of CTE research is coming from. The movie concussion, which I still have yet to be able to sit and watch it directly talks about CTE. But the research has been in the football world, a little bit in soccer, a little bit in boxing. (00:30:19): But Dave was starting to exhibit a lot of those symptoms. But because CTE was still brand new, we still can't wrap our heads around it, no pun intended. It was hard to find anything until after the fact, which they were able to successfully diagnose that. And with me, there's enough factors to see that it's not just complex childhood trauma or complex depression or anxiety or any of that, that there very much is a maelstrom of things happening all at once. As my wife tells me, she tells me all the time, Hey, you've been like this since I've known you. I've known my wife for 19 years now, but the progression hasn't changed. I have not. And I've been on medication for depression and anxiety, and I'm still on medication for depression and anxiety. And normally under the dosage that I've been on, I theoretically should have improved. (00:31:56): Now, at times, I exhibit mental clarity, which I'm able to hold on to, but I do have frequent times where I just can't think or I get really dark and the world kind of shuts out from me. And I go into myself and I'm like, whoa, wait a minute. And I've had extensive therapy and hypnotherapy and EMDR, which is electromagnetic displacement, something, I don't even, it's where you use magnetic impulses to take your trauma. And because with PTSD, your trauma lives in, your vision essentially lives right here in front of you, and you relive that trauma constantly. And with the therapies that I do and have done, it's been proven with soldiers coming back from war who exhibit PTSD, they take this therapy. And what it does is it files it away back in the recesses of your brain where things like this should be so you don't relive it every day with PTSD, you're reliving the trauma. (00:33:23): And I've undergone years of these types of therapies, and I've put away a lot of the trauma from my past, but symptoms like the constant ringing in my ears. I have this dial tone, this tinnitus in my head that is 24 7, literally 24 7. And at times it will completely block out all noise. And the only thing that I hear is this dial tone and people will be talking to me and I'm just like, I can't hear you. And that happens a lot. The feeling of my brain feels like there's a porcupine inside of it rolling around, but it said it's quills on fire. So I have these hot quills in my head all the time, and they tend to be singular hemispheric. So I feel it all in the left side of my head. I don't feel it by hemispheric. (00:34:39): I'll lose my vision for no reason at all. Everything will just go blurry. I have this irritability about me that is similar to drinking four red bulls in a row that I have to laugh about it because I've done the four red bulls in a row, this constant irritability that is like, I need to keep that in check. And I do that through meditation. I do it through medication, I do it through mindfulness, measuring myself at computer speeds. I have to reimagine my head as a CPU and the processing of my brain processing power. And I have to be aware of when I get overwhelmed, which I get overwhelmed really easy. And that may or may not be an autistic trait that I have. It may or may not be a trauma response that I have. It may or may not be a CTE response that I have, but it's there. (00:36:10): And I have to treat everything as if it is a CTE response because that is the number one thing that is causing a shelf life to me. And if I'm not careful, I will not see my children graduate high school and I am 47 and there is a real possibility that I won't see 50, I won't see 60, I won't see 70, and I need to live my life that way, but I need to live it in a positive way, not in a Hunter Thompson way. So like, oh yeah, you got one life. Let's do this. It's like, no, I've got very specific reasons to be here and to make sure my sons don't live the life that I was raised in. I want them to have beautiful lives. I want to make sure that the world is going to be here for them, which is a whole nother level of stress that I have. (00:37:27): And I complete tangent. I don't want to go down right now. But when I had that meeting with my doctor and it was like you sitting down, I'm like, oh, yeah, I'm sitting down. Take a big breath. Okay, I'm breathing. Here you go. And wow, okay. And that was the thing. It was seeing it on paper. I had a, had lots of scary close calls in my life with going down the bad road and lots of issues as I've said. And just seeing it on paper as an official diagnosis, it just made it so much more real and like, okay, we're here now. Let's not let it scare me into submission, but let's find ways to work with this and find ways to be okay with this and take it one day at a time and sometimes one hour at a time, and it can be a hindrance. (00:39:01): There's no question. It gets in the way of work. It gets in the way of home life. It gets in the way of friendship. I've lost friends, I've gained friends, I've had any number of things. And that's, my wife has been an absolute Gibraltar rock. She's there. She's not a melting glacier. She's not going anywhere. And she's been through me through all of this, and it's been amazing. And even now here at FSA, my managing director props to you like Mark, dude, he is the only boss I've ever had that understands, or he has a friend who has the same diagnosis, and he gets it. And it feels good to be able to be seen and to know that if I make a mistake, which I make a lot of mistakes, it's okay because it is what it is, and I'm okay. And it makes it so that I, well, slight digression, I am a really empathetic person, but when I hear about others hitting their head and Oh, I'm okay. (00:40:54): I'm like, no, I'm like mother hen or mother bear. I've had friends that have hit their heads on rides, and I'm like, no, you're sitting down. You're not going anywhere. Okay, we're going to sit here for a while. And it's something that isn't talked about enough in our sport. It's part of it is cycling in North America and very specifically in the us, cycling is still not looked at as legitimate, really. It's still like a kid's thing in Europe. It's much bigger. There are significantly more safety protocols that are being put in place. And props to UCI for that. You'll not hear me of UCI mini props, but that's one of them. And they're leading to bigger safety protocols, especially in downhill racing, Enduro racing. And that's leading to better safety products in the industry. And you look at companies like Kelly Protectives, who I exclusively wear their helmets bits because of a story that Brad, the owner told me in 2006 when I first met him, and they were first starting, Brad suffers from quite possibly CTE as well. (00:42:24): He had multiple head injuries, and he doesn't want to see anyone sustain the kind of injuries that he sustained. So he makes some of the safest helmets in the world because of that. And I support him wholeheartedly with my paychecks too, because I believe in what he's doing. And then you get the guys over at 60 helmets who are doing the same kind of thing, who are now trying to push their technology into other sports like NFL and even soccer and hockey and boxing helmets. And you get mips, which is evolving into something bigger for the same reasons, and branching out into other sports and baseball even. And there are baseball hats that you can get with MIPS inserts and MIPS nets in them to help. And I have a specific insert that I'll wear in a hat sometimes with a D three O style gel so that when you get hit in the head wearing this hat from a flyball, you're going to be okay. (00:43:46): You're not going to sustain a concussion from it, which has happened to me playing baseball. I got hit in the head from a flyball goes, oh, look at that smack. Oh, great, because of my farsightedness. And so there's progress, but it's not fast enough I think in terms of normalizing it. And that's one of the, that's probably the biggest reason that I wanted to be here on this podcast is it needs to be normal. It needs to be okay for us to talk about our mental health. Katie Winton who had, she's an Enduro racer for gt. She had a really bad concussion, I want to say it was towards the end of last year. And she sat out almost an entire year because she just wasn't feeling right. And she was slow to be open about it, and she would just say, no, I'm not ready. (00:45:07): I'm not ready. She's slowly starting to talk about it now. It's like, okay, yeah, she had a really serious TBI and it really affected her. Finn Isles sat out of the world or World Cup. He was the final World Cup going into the World Cup of the season. If he won the race, he would've won the overall World Cup. But he sustained an injury the week before, and he was like, I'm not going to risk my life and my health for this race. There will be other World Cups to win. And I've known Finn since he was a little grom, and I have got so much love and respect, Finn, for doing that and openly talking about it. Win masters, same thing a year or two ago, suffered a concussion. (00:46:10): Him and me talk about concussions and brain injuries whenever we see each other. And Brooke McDonald and me do the same. It's something that we don't talk enough about. The US itself has a stigma about mental health. We're like, oh, yeah, no, we treat the symptoms. We don't treat what's actually happening in the brain. We think, oh, you need to be normal. You need to be able to work. You need to be a functioning adult in society or a functioning normal kid who is seen and not heard, and you do your work and things like that. This is all bullshit if someone's having an off day because their brain is not there. (00:47:10): Humans are the sum of everything. We're the sum of our emotions. We're the sum of our physical actions. We're not just this body walking around. We are this living, breathing, electrical entity that our soul being is this CPU that's inside of our head. And if that thing gets crosswired or hot booted in a way that messes us up, we're going to have a bad day. And those around us are going to have a bad day too. And it's, the conversations around that always are like, oh, you're seeing a therapist. Oh, you're on medication. Not, Hey, I'm on 30 milligrams of Lex Pro, which is above the FDA recommended amount because I was specifically placed on that because of my mental health, because my anxiety levels and my depression levels and my irritability and everything is so high that I was institutionalized for over a week, 52 50. (00:48:40): And I've been on the same medication for four years, and I've actually tapered down to this higher dose from where I was at because this the CTE, the trauma, but the antin normalization, it's like I feel ostracized sometimes, and I know others who feel the same. It's like there's no shame or harm in going to a therapist. Everyone needs a therapist. Everyone needs to have someone to at the very least, talk through things to help your brain digest what's happening to you in the world. Because at the primal level of humanity, humans are a social creature. We come from a society of evolution of primates. We are a primate and we're a social primate. And the constructs that we placed on ourselves brought us to where we are now, where it's not cool to have a mental disability. It's not cool to need to seek help. It's not cool to talk to someone on average. It's not cool to on medication. It is cool to power through a head injury. It is cool to be a man or suck it up or whatever it is. And even with women, it's like, oh, she's just being a no no, that's not cool. (00:50:59): That person is probably just having a bad day. They don't have a therapist to talk to because they're under this construct of, Hey, you need to do it all. You need to be a mom. You need to work a job. You need to have an income. You need to be a perfect partner for your partner. You need to have all of these things. You need to keep a clean house. It's like, oh my God, no, you don't. You need to be a human and you need to listen to your heart. You need to do what's right for you as a person. And that those conversations are not being had, at least not that I'm hearing. Even when I talk to my friends about it, it's still, I have two very close dear friends, and they check in on me and I check in on them. (00:51:59): And we started this circle a long time ago that was, Hey, we're going to lean on each other. We're going to be there for each other. And just even if it's sending each other a meme once in a while, one of my dear friends, every Thursday, like clockwork, he sends me a photo of him on a bike ride, and he's like, dirt church on Thursday or living it up. And he's just soil sampling. And that's all it takes, just the little check-in to know, Hey, we're all here. We're all here together, and we're having these conversations together and being able to bring it out in the open, which I try and do at events that I go to. I get people at events coming up to me and they're like, dude, tell me about this handlebar. And I'm like, I'm going to tell you about this last time, but I hit my head and I'm like, I'm not feeling good. (00:53:05): Or I'm going to be like, yo, describe this wheel to me and I'm going to be like, yo, you know what? I ate some really bomb food over here because we're humans and we need to connect as a human first. Okay, I'll tell you about this product. It's cool, whatever, which it is. I got to give a plug, but tell me how your day is for real. Hey, I am not feeling too well. I'm having this buzzing in my head, and so I may not be able to follow your conversation too well, but I'm here and I'm going to be here. I'm going to show up for you in the words of Brene Brown, I'm going to show up for our conversation. I'm going to be there for our conversation. So prefacing those kinds of conversations, which I've done with media, with athletes, especially with athletes, and as an athlete manager, that's my number one concern. (00:54:13): If I have an athlete who's injured, nothing else matters. I don't care if you are two points away from winning a World cup. If you're hurt and you're my athlete, I'm going to call you and I'm going to say, Hey, we're going to talk. Are you okay? No. I mean, are you okay? Somebody kick your puppy. Okay, or what's going on? Let's have this conversation. You know what, I'm not okay, and here's why I'm not, okay, so let's talk. And those conversations happen over the phone, but they don't happen enough in everyday lives, and they need to normalize being human, if you will, and normalize the experiences that we all have individually. (00:55:21): You could a prime example, road rage. Everyone's experienced road rage. It's like, no, that person who just cut you off, maybe they're in a hurry because they got into an argument with their significant other in the morning and they're running late for something, or maybe their child is sick and they're scared and they don't know what to do and they're running fast and they cut you off. It's like, don't get aggressive back at them. We need to start giving each other grace. And the more that happens, the more bandwidth humans will have to be able to have the bigger, harder conversations. And those conversations are they're going to be difficult, but they don't need to be because we all have them because we're all the same creature. (00:56:28): We're all having the same experience. We're all here on the same planet, breathing the same oxygen, drinking the same water that the dinosaurs drink because nothing has left or been created. We're part of this continuous process of life. And that's something that I think everyone forgets and having a wake up call of, oh, you got a shelf life, opens that up. And it's like, okay, yeah, I get it. It's normal for me, but it may not be normal for the next person. But you know what? You're breathing oxygen. I'm breathing oxygen. You are walking on two legs or you're in a wheelchair, or we're both sitting down and having a beer together, or we both enjoy chickies when they're calling. We're all the same creature. And we need to normalize that before anything else can really be said. And that's something that society put upon that we created. (00:57:53): We're like, okay, we made this society. Now we're going down this rabbit hole of we're nothing more than cogs in this machine. And we do what we think society is supposed to be telling us to do, but we forget along the lines that, Hey, this person over here and that person over there, we're all the same creature. We're all experiencing the same experience, but just through different eyes and different lenses. And before you know it, you're in a pine box or in a feeding a tree somewhere, or you are sick and you're afraid to ask for help because you've never had those conversations. Or worse, you're all alone in a closet somewhere crying and holding a razor blade because you're afraid we need to not be afraid to reach out to each other. And that's something that is just, it's one of the T tragedy, the great tragedies of humanity. And I know I've gone down this crazy tangent, I think, I don't know if it's anywhere related to where we were going, but I feel it's very apropos. But yeah, so that's kind of been my experience with it.", "token_estimate": 5856, "speakers": ["David Meredith"], "start_timestamp": "00:19:33", "end_timestamp": "00:19:33", "podcast_index": 121, "episode_name": "EP 121: Mental Health and CTE in the Workplace | David Meredith | Full Speed Ahead", "slug": "ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "web_url": "https://www.portsidepro.com/podcast-feed/ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "guest_name": "David Meredith", "guest_title": null, "categories": [], "short_description": "David Meredith is the Dirt Marketing Manager for Full Speed Ahead and has been in the bike industry for years, including racing, owning a retail shop, and operating his own international bicycle brand. David comes on the show to share his experience in the bike industry, but also, to share his experience being a human pre-diagnosed with CTE, Stage 4. In this episode, David and Cole discuss:", "podcast_length": "1:15"}, {"id": "44864578-c318-453e-b35e-a4e2ac46abad", "episode_id": "7d754328-473d-4dfc-9a75-5e43416491ba", "cms_item_id": "68225dfc7bb476527f8c489e", "chunk_index": 5, "content": "David Meredith (00:59:35): I appreciate you sharing as you've been talking. There's been a lot of things that I've just been pondering and thinking about, and there's so many different takeaways I think from your experience. But I think what stood out to me the most is just how many of us really know what's happening in our colleague or our neighbor's life? Do we really take the time to stop and understand on a deeper level rather than just saying, how are you doing? Do we really take the time to get to know someone and to get to understand how someone's feeling, as you said, and as you experienced as we all experienced, there's so much more that happens behind the scenes that we constantly are dealing with and figuring out how to push through each day. And I think you leave us with a great reminder that we all need to give each other more grace. We all need to, because consider the other person more because at the end of it, we have our relationships, and that's about all that matters at the end.", "token_estimate": 253, "speakers": ["David Meredith"], "start_timestamp": "00:59:35", "end_timestamp": "00:59:35", "podcast_index": 121, "episode_name": "EP 121: Mental Health and CTE in the Workplace | David Meredith | Full Speed Ahead", "slug": "ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "web_url": "https://www.portsidepro.com/podcast-feed/ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "guest_name": "David Meredith", "guest_title": null, "categories": [], "short_description": "David Meredith is the Dirt Marketing Manager for Full Speed Ahead and has been in the bike industry for years, including racing, owning a retail shop, and operating his own international bicycle brand. David comes on the show to share his experience in the bike industry, but also, to share his experience being a human pre-diagnosed with CTE, Stage 4. In this episode, David and Cole discuss:", "podcast_length": "1:15"}, {"id": "a645aed8-a08b-48ac-b3b3-75cb18cfd891", "episode_id": "7d754328-473d-4dfc-9a75-5e43416491ba", "cms_item_id": "68225dfc7bb476527f8c489e", "chunk_index": 6, "content": "David Meredith (01:00:49): It is, as Michael Franti puts it, stay human. And that's a mantra. Don't forget not just where you came from. Yeah, sure, everyone came from somewhere, but literally don't forget what you are. You are not the sum of your bank account. You are not the sum of the stuff that you own. You are not your car fight club, the song from Fight Club or whatever. The mantra from that. It's like you not your double tall latte. You are not where you work. You are not the products that you sell. You are not anything more than you are the sum of the neurons that fire, the synapses, the gray matter in your skull, the blood that's working through your body. You're this physical creature with a soul or with brain function, whatever you believe in, it doesn't matter. You're this living creature. (01:02:22): And that opens up a whole new window. It's like, okay, I'm a living creature. My dog is a living creature. The birds outside are living creatures. And it's like, that is where I feel the human ego kind of takes over too. And it's like, okay, without digressing too deep into religion and other things, humans in my experience forget that they are not different than every other living creature on this planet. Humans can forget that, and they can think that they are a superior creature or a superior race, all because they created cars and because they can fly airplanes. Do you think a dog wants to fly an airplane? Dog is happy being dog. Humans are the only creature on this planet that is not happy being itself. (01:03:40): And that's something to think about. And we are a very complex creature. But you know what? So's the dog. It's like, so are most insects actually take for example, a roach, which they're gross. Yeah, they're gross. But roaches, roach parents care for their young and will carry their young around with them like a possum. Now that's weird and kind of gross, but you know what? That's a living sentient creature just like a human. And people don't want to compare themselves to a roach, but I just did. So we're all interconnected and we all need to stop and take time and be like, yo, I am a living, breathing creature. I'm here on this planet partaking in what this planet gives me. And my time is very short on this planet. There are many other animals that will outlive me, provided I let them. There's tortoises that live hundreds of years. An elephant has a longer life expectancy than a human as long as they're not poached. And humans get wrapped up in their own ego of superiority because we make things like airplanes and we forget how fragile we are that it takes one solid hit to the head and all of a sudden your life changed. (01:05:51): It takes one good solid hit to your spine and you lose your legs. We are an incredibly fragile creature for an absolute plethora of reasons. You scrape yourself on a box and you bleed. And I think humanity takes that mortality for granted sometimes. And along with that, our mental health and being able to say, Hey, I'm not doing well today for whatever reason, it doesn't matter. It's your experience. It could be something like, I tried to pay my phone bill and I didn't have my credit card with me to pay my phone bill on my phone or whatever, so I got to wait until I get home. And it is kind of upsetting because it's going to be late. Or it could be something as simple as going to the grocery store and them being out of apples and you're like, I really want this apple and they're out of them. Or a long line at the gas route, getting gas in your car. (01:07:20): It doesn't matter what is going to put you off into a different mental state. What matters is taking account of that mental state and not being afraid to say, Hey, I'm feeling off. I'm not all there right now. Am experiencing some brain fog. I'm experiencing some weird tingling. I can't fully hear you right now. And being able to just be okay with those things and being able to ask those things too, and not just the pleasantries of How you doing? Oh, I'm okay. No, you're not because you're a human and you're inherently not okay because you're a human. (01:08:31): Excuse me, it's so many things. But being able to say, okay, yeah, how are you, Robert? Oh, I missed the ferry this morning. And so I was running late, so I got really frazzled to get to work, and now I can't get on track. It's like, well, hey, I'm going to hold space for you, buddy. Let's take a deep breath. Let's forget about this. This is this. We're going to be you and me and we're going to be okay, and you're going to be okay. And be like, okay. Yeah. And then when people come back at you and be like, Hey, how you doing? Oh yeah, it's sunny out. I'm doing okay. Well, no, are you really? I have friends that say, are you really, they'll lean into that question and be like, well, no, X, Y, Z. So now I'm like A, B, C, and things are not feeling right for me. Oh, well, I'm going to hold some space for you for that. I'm going to show up for you and be here for you to say, okay, yeah, that's not cool. Or, I hear you and I'm going to be, we'll be okay, and I'm going to be here with you for that. (01:10:10): And those things start with ourselves. They don't start with conversations with others. They start with us and being able to mentally and emotionally look within and say, Hey, something's not right. Okay, let's be aware of this. And having that mindfulness and that we're not talking like Zen monk meditation, mindfulness stuff. You don't need to be someone that meditates five minutes a day. You don't have to meditate at all. It's just being show up for yourself. And then when you show up for yourself, you can show up for others and then they can show up for others and they can show up for themselves. And you create this butterfly effect by doing that, and maybe we'll be able to survive the next apocalypse because we're all on the same page by that time. That's my dream for humanity.", "token_estimate": 1491, "speakers": ["David Meredith"], "start_timestamp": "01:00:49", "end_timestamp": "01:00:49", "podcast_index": 121, "episode_name": "EP 121: Mental Health and CTE in the Workplace | David Meredith | Full Speed Ahead", "slug": "ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "web_url": "https://www.portsidepro.com/podcast-feed/ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "guest_name": "David Meredith", "guest_title": null, "categories": [], "short_description": "David Meredith is the Dirt Marketing Manager for Full Speed Ahead and has been in the bike industry for years, including racing, owning a retail shop, and operating his own international bicycle brand. David comes on the show to share his experience in the bike industry, but also, to share his experience being a human pre-diagnosed with CTE, Stage 4. In this episode, David and Cole discuss:", "podcast_length": "1:15"}, {"id": "becb7513-946a-496a-8c9b-f9627c636a4e", "episode_id": "7d754328-473d-4dfc-9a75-5e43416491ba", "cms_item_id": "68225dfc7bb476527f8c489e", "chunk_index": 7, "content": "David Meredith (01:11:31): David, are you open to folks reaching out to you if they're interested in having a similar conversation or just sharing in life together, or is that something you're okay with?\n\nDavid Meredith (01:11:43): Yes, very much. I'm very okay with that.\n\nDavid Meredith (01:11:47): How can people get ahold of you if they want to chat?\n\nDavid Meredith (01:11:54): Well, it depends on, well, it doesn't really depend. My personal Instagram is at Go Ari, again named after my dog. His full name was Ghost Ari because he started his own religion. Go Ari. Deism Green is the grass that he rolls around in. Gold is for the sun, for the sunbeams, red is for the color of his hair, and black was for his nose or something. I don't remember. But it was this fun little thing that we did. Red gold, green black, but at Go Tafari for an Instagram, I'm on LinkedIn, it's just DG Meredith on LinkedIn, or David Glenn Meredith on LinkedIn. I'm open to those conversations at any time. I'm always in front of a device. Thank you autism for being that way. But I, I'm open to everyone in those conversations and I'm here.\n\nDavid Meredith (01:13:10): Well, I want to thank you again for sharing your story. I don't know who needs to hear it, but I appreciate you being willing to share it for those who are out there who need to hear it. And I encourage everyone to just take a breath and I dunno, there's so, so much perspective out there to be gained. And I feel like David, you've just kind of scratched the surface with a lot of stuff to think about. So maybe if you're listening to this episode, take 10 minutes before you jump into your next task and just think about some of these things that David has discussed. David, do you have any final words for our audience?\n\nDavid Meredith (01:13:54): Stay human. Take the time and listen to your heart and just be there for yourself and the rest will happen. And thank you, Cole, for letting me tell the story and letting me be here. It's these kind of conversations really, it take weight off of my heart, and I thank you for that.", "token_estimate": 522, "speakers": ["David Meredith"], "start_timestamp": "01:11:31", "end_timestamp": "01:13:54", "podcast_index": 121, "episode_name": "EP 121: Mental Health and CTE in the Workplace | David Meredith | Full Speed Ahead", "slug": "ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "web_url": "https://www.portsidepro.com/podcast-feed/ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "guest_name": "David Meredith", "guest_title": null, "categories": [], "short_description": "David Meredith is the Dirt Marketing Manager for Full Speed Ahead and has been in the bike industry for years, including racing, owning a retail shop, and operating his own international bicycle brand. David comes on the show to share his experience in the bike industry, but also, to share his experience being a human pre-diagnosed with CTE, Stage 4. In this episode, David and Cole discuss:", "podcast_length": "1:15"}, {"id": "28e75ea7-e5bd-41e1-a240-b4ac7f014ad1", "episode_id": "7d754328-473d-4dfc-9a75-5e43416491ba", "cms_item_id": "68225dfc7bb476527f8c489e", "chunk_index": 8, "content": "David Meredith (01:14:36): Absolutely. Anytime you got my email, you, if we want to chat, have a great rest of your day. I will. And I look forward to staying in touch and seeing how you're doing in the future.\n\nDavid Meredith (01:14:47): Thank you very much, sir. I appreciate it. You too. Bye\n\nCole Heilborn (01:14:50): Bye. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 135, "speakers": ["David Meredith", "Cole Heilborn"], "start_timestamp": "01:14:36", "end_timestamp": "01:14:50", "podcast_index": 121, "episode_name": "EP 121: Mental Health and CTE in the Workplace | David Meredith | Full Speed Ahead", "slug": "ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "web_url": "https://www.portsidepro.com/podcast-feed/ep-121-mental-health-and-cte-in-the-workplace-david-meredith-full-speed-ahead", "guest_name": "David Meredith", "guest_title": null, "categories": [], "short_description": "David Meredith is the Dirt Marketing Manager for Full Speed Ahead and has been in the bike industry for years, including racing, owning a retail shop, and operating his own international bicycle brand. David comes on the show to share his experience in the bike industry, but also, to share his experience being a human pre-diagnosed with CTE, Stage 4. In this episode, David and Cole discuss:", "podcast_length": "1:15"}, {"id": "b08c6a9f-1130-4c04-ad2e-5a55e956335e", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 0, "content": "Cole Heilborn (00:00:00): Welcome to the Backcountry Marketing Podcast. Today I'm sitting down with Becky Little, she's the VP of Product Marketing, and Alex Willie, the account executive over at Expert Voice. Becky and Alex, how are you both?\n\nBecky Little (00:00:13): Great, thank you.\n\nAlex Willie (00:00:14): Yeah, we're excited to be here. Thanks so much for having us.\n\nCole Heilborn (00:00:18): Absolutely. I can't remember the last time that we had two guests on the show. It's been at least over a year, and I don't know why. It's a ton of fun, and so I'm excited that we get to break this ice again.\n\nAlex Willie (00:00:35): Double the trouble. Right? You got to deal with both of us now.\n\nCole Heilborn (00:00:39): Something like that. Becky and Alex, where are you both calling in from?\n\nBecky Little (00:00:43): Actually, we both happen to be based here in Salt Lake City,\n\nAlex Willie (00:00:46): Taking advantage of the fall time weather we got here, so it's beautiful this time of year.\n\nCole Heilborn (00:00:51): Awesome. Well, I'm really excited that you guys could join us on the show. I got to be honest, I feel like it wasn't until two years ago that I realized what a pro deal was. I don't know how, I never knew about it. I always heard about 'em, but I never feel like I properly understood them. And so I'm excited for a number of reasons to have you guys on the show and diving into what you guys do day to day and talking about things in your world. So I loved if you guys could just kick us off and maybe give a quick introduction on yourselves, a little bit about your roles with the company and some background on Expert Voice.", "token_estimate": 415, "speakers": ["Cole Heilborn", "Becky Little", "Alex Willie"], "start_timestamp": "00:00:00", "end_timestamp": "00:00:51", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "fc41107f-bbdc-4064-b253-80ee96fab27f", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 1, "content": "Becky Little (00:01:32): Sure, I can jump in. I've been with Expert Voice, just celebrated seven years last month, but prior to that I spent about 15 years in the nonprofit world, including eight years with US Ski and Snowboard teams. Got to do a couple Olympic cycles with them, but also worked for Multiple Sclerosis. But now I get the exciting role of helping Expert Voice launch new products to our customers, whether that's brands and or we're a two-sided platform. So we have a whole member base of people we call experts. So they have some kind of credential or verification that says, Hey, I deserve to have better access. I should have insider access to brands. And brands are saying, Hey, these are people I want to connect with because I know that the recommendations they give, whether that's online or out in the world, are going to make a difference to consumers trying to decide what to buy.\n\nAlex Willie (00:02:20): Yeah, that's a great summary and what I get to do, which I love, I get to work with the brands that we partner with to develop that strategy. So we identify who these individuals are that are impactful for them because different for every single brand, every industry is different, and so we're able to really customize who we're targeting with these efforts and then what these efforts look like are educational content. So how do we get the retail sales associates, the industry professionals, knowledgeable about not only the brand but the product, and so they can speak more educated about the brand and the product to be able to give a better recommendation to the end consumer. So really fun. Get a dive in with a multitude of different brands across a handful of different industries to make sure that their advocacy marketing solution is exactly what it should be.\n\nCole Heilborn (00:03:14): Becky, you mentioned that there's kind of two sides to expert voice. There's the brand side and then there's the individual side. Could you further break down what that looks like in a day to day?", "token_estimate": 507, "speakers": ["Becky Little", "Alex Willie", "Cole Heilborn"], "start_timestamp": "00:01:32", "end_timestamp": "00:03:14", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "1c6cd1bc-3bb9-4465-b583-0ec24f7de4d7", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 2, "content": "Becky Little (00:03:25): Sure. So yes, I'd say the brand side is what you might traditionally call the B2B side of our platform. And as Alex alluded to, we cover several categories. So that's anywhere from outdoor to animals of pets to health and nutrition or wellness and a myriad of others. And those brands are coming to us looking for solutions. How do I get more people talking about my brand and better recommending my brand? We service those brands through both a hands-on services approach. We have a whole studios team that builds educational content, builds the store experience, but then they also have access to what we call the advocacy platform, which is a self-service SaaS environment where they can come in, build their own programs, decide what they want to be launching when, what kind of campaigns are important to them, depending on what messaging is important. The expert side of the audience is, I kind of think of it like a marketplace for the experts where it's a one-stop shop where they can come in and engage with all the brands that are important to them depending on what they have access to, depending on their expertise and the verification. (00:04:24): So they can come in and see every brand that we work with in the ski category, they can come in and learn about those brands that can come in and have access to their pro deals. They can engage with brands in other ways. Their brands might be looking for survey feedback. Their brands might be looking for candidates to join their community. They might be looking for people that can help them launch their next new product. So that's the expert side of the experience or what you might think of as the B2C side of our platform.\n\nCole Heilborn (00:04:50): Gotcha. So it all goes well beyond just your basic pro deal. There's a lot of backend, there's a lot of tools and support, and the pro deal is just kind of the tip of the iceberg.\n\nBecky Little (00:05:02): Yeah, I'd say the pro deal might be the gateway drug for brands to come and join the platform. I don't know if that's official marketing speak.\n\nCole Heilborn (00:05:11): And how many brands do you guys work with?", "token_estimate": 541, "speakers": ["Becky Little", "Cole Heilborn"], "start_timestamp": "00:03:25", "end_timestamp": "00:05:11", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "057f732b-f0ce-4854-8357-8b76d8f54f13", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 3, "content": "Alex Willie (00:05:15): We currently work with what, just over 900 brands right now. So yeah, it's been fun to watch it grow. And to Becky's point, right, they come in, they might think, Hey, maybe we need a way to get product in the hands of these individuals, but man, we can use just so much more for the brand and the experts and kind of create that mutually beneficial experience for both parties.\n\nCole Heilborn (00:05:39): How long has the company been around? Can you kind of give us a little bit of the background on how it got started?\n\nBecky Little (00:05:46): Yeah. It started back in the early two thousands. It was literally a solution to help brands do pro deals at scale. Used to have, I was a ski instructor for years, and remember meeting the rep in the parking lot. He would hand me a piece of paper or sometimes I'd buy things out of his trunk. I'm not sure if that went through the company or not, and that's not scalable for a brand. And so expert voice at the time, we went through several name changes, but the side of our platform was the profor side. We had 3.5 for retail associates and we had promotive for the industry professionals. And it was literally just getting the proform online, allowing brands to do that at scale so they could just hand out a website, people could go on and verify and place their order. It's since evolved over the years realizing that that's just one small part of what we can help brands do. Why do brands do a profor, right? They do it to get more of the right people using their gear, hopefully talking about their gear, but just getting the visibility out in the environment. And over the years as our platform has evolved, we've been like, you can get so much more out of what you're doing when you're trying to sell discounted product to the right people.\n\nCole Heilborn (00:06:54): And could you summarize what is a pro deal? Where did the idea of a pro deal come from and how has it evolved to where it is today? Or maybe it stayed the same.", "token_estimate": 502, "speakers": ["Alex Willie", "Cole Heilborn", "Becky Little"], "start_timestamp": "00:05:15", "end_timestamp": "00:06:54", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "53d6115b-5b4e-40b0-b4bc-888adee491c2", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 4, "content": "Alex Willie (00:07:06): My experience, I worked in the bike shops, so as a kid, how do I get my hands on those cool new products, how I am able to use those products so I can speak about it when people come in and learn about, Hey, what pads do you, what handlebars do you like to ride? The best way I could speak about that is my own firsthand experience. I'm not going to recommend a pad or a helmet that I haven't used. And so I think that's really at a core of what drove, how do we get people speaking about these products or these brands in the right way? If you're going to ask for advice on what product to buy, you're probably going to go ask someone that has a great amount of experience, either in the industry or is using that product themselves. What do you love about it? (00:07:54): What do you hate about it? If you were to buy another one, would you get another one or would you get the exact same? And so I think that's continued to evolve over time where man, there's something to this advocacy marketing. As consumers are getting smarter and smarter, they're listening less and less to what the brands say about themselves. Instead, they're doing their own research. They're going on online, looking up blogs, trying to find these micro influencers or these massive influencers about what do they have to say about certain experiences that they're having with certain products. So I think the main catalyst to this evolution is the consumers getting smarter and they're kind of blocking out some of the noise of what traditional marketing channels kind of produce.", "token_estimate": 396, "speakers": ["Alex Willie"], "start_timestamp": "00:07:06", "end_timestamp": "00:07:06", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "c2abb181-9183-4a8b-9081-1b06b62b71e5", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 5, "content": "Becky Little (00:08:42): And then I think I'd tag on there is if you think about it from the brand side, yeah, it started out with just help me find the people that should be wearing my product. The people that I know, people are asking for advice and realizing over time they didn't know what they were getting from these people. That's proform. Some of them in some cases were just dealt left. And if you were using a platform that had some kind of vetted verification or credential, then at least you knew they were going to the right people. But the brand didn't know anything else about those people. They weren't getting anything back from those people. They were still just selling at a discount in hopes that it was landing in front of the right eyeballs and the right things were coming out of their mouth. And there is an opportunity to do that a whole lot better.\n\nCole Heilborn (00:09:24): Interesting. I'm curious if you guys could share what was a piece of product, piece of gear that you've most recently purchased? And I'm curious, how did you make the decision to purchase that particular product? How did you vet it? How did you research it?", "token_estimate": 290, "speakers": ["Becky Little", "Cole Heilborn"], "start_timestamp": "00:08:42", "end_timestamp": "00:09:24", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "55cb9db2-28c1-4015-bce2-e7b49251adce", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 6, "content": "Alex Willie (00:09:41): Yeah, well shoot, I might be a little biased here, but some last product I bought, I got a new inReach, so an inReach mini. So when I'm out hunting out, snowmobiling out, doing all my adventures in the summer or winter, I want to be able to text my wife, text my parents, text my brother, let 'em know, Hey, I'm back at camp tonight. Okay. Gives you a little bit of comfort too when you're back in the back country for a handful of days. So the first thing I'd like to do, man, I want to learn everything there is to know about that product. I want to see what the brand has to say. I want to see YouTube videos, I want to see, I'm going to talk to other buddies that I know already have that product. Hey, what do you love about it? What do you hate about it? You get a different one. And so I think again, as these consumers, I hope I fit in this category, are getting smarter, right? I'm not just looking and believing every single thing that the brand is saying, what Garmin is saying about this inReach, I'm going to go ask my buddies, Hey, what do you love about it? Is there another one I should be looking at? Right? They have Alio. What's the perks of that product as opposed to inReach? What's the subscription plan look like? (00:10:52): And then reading those reviews, understanding what do other people using them every day, what do they have to say to make sure I'm making the best purchase for myself?", "token_estimate": 360, "speakers": ["Alex Willie"], "start_timestamp": "00:09:41", "end_timestamp": "00:09:41", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "1e7b07a4-6fd4-4cfd-a689-0d179e285385", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 7, "content": "Becky Little (00:11:01): I think probably one of the more recent products I purchased was upgrading my trail running vest and trying to decide what the right option would be. I have dogs that are older now, they used to run with their own trail pack, but I know that now they don't last as long when I make them carry their own water. So I need to be able to carry extra water and what pack was going to help me do that most efficiently. And so researching online, reading, everybody's reviews, what they're saying about the product, looking through the trail runner magazines to see what people are just actually wearing out on the trails. And then being at races and events and talking to some of the reps at the bottom of the mountain and saying, okay, lemme go try it firsthand for myself and then make your decision.\n\nCole Heilborn (00:11:44): Do you guys feel like in today's world where there's so much information and brands are putting out so much information and content about products that there's, I guess I'm curious. Before pre-digital, when we would go buy a product, you would go to the store, you would talk to the rep or you would talk to your friend, and I guess I'm simplifying, but those seem seem like the two main ways that we would get our information about how we'd purchase a product. Then the digital world kind of blows up and now we have all this information we can go and listen to, and now maybe we have too much. Do you feel like there's a trend coming back to trying to find that personal, that person, that friend, that sales rep, the buddy on the ski hill who can give you the lowdown?", "token_estimate": 405, "speakers": ["Becky Little", "Cole Heilborn"], "start_timestamp": "00:11:01", "end_timestamp": "00:11:44", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "dfa2a3aa-9ef3-4258-86f0-b7542de3775f", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 8, "content": "Alex Willie (00:12:33): Absolutely. I think the way I look at it and the way that we'll explain it quite often to brands is we are building the solution for them understanding what audiences should get, what experience. I think of it as man, you might have someone, for sake of example, a Kim Kardashian, so many followers, she's reaching millions and millions of people. If she's talking about a product, her reach, sure it's huge. But the amount of those individuals that are actually going to act on that recommendation are probably pretty small, but she's touching a lot of people versus your brother-in-law, your sister-in-law. If your best friend, if you're asking them about a recommendation or a product, their reach is incredibly small, maybe just close friends, family members, a man, that power of that recommendation is incredibly strong, so you're much more likely to act on that as opposed to what you're seeing online. (00:13:32): And so I think as this digital story to what you just mentioned has evolved, and as consumers are becoming smarter, they're kind of having to suss out what information is credible, are they seeing, oh, it's a sponsored post, so they're probably going to incentivize in some way here to say these great things about this product. Or man, they're probably just being handed this product by this company to go and use it. They have a million followers, versus this is a truly authentic relationship that this individual had with the product. They bought it themselves, they're using it themselves every day. And so that recommendation or that interaction might be a little more credible in being able to act on it. So with this overwhelming amount, I think people are just having to be more cognizant of what information to trust and where are they gathering that information from.", "token_estimate": 456, "speakers": ["Alex Willie"], "start_timestamp": "00:12:33", "end_timestamp": "00:12:33", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "56eac1bf-8e9e-4873-8839-9297adadf969", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 9, "content": "Becky Little (00:14:24): Yeah, and I think I watched it firsthand just the other weekend, my father-in-law, his umbrella stand broke, right? It was a cement basin, it crumbled. And my husband was like, well, you just need X, Y, and Z and send him a link. Well, next two hours later, he still on searching through reading hundreds and hundreds and hundreds of reviews and Scott's like, just buy one. Darn it. What is wrong with you now? Guaranteed one, if he had gone to the store and a retail sales facility had said to him with some kind of authority, this is what you need, he would've walked out the store that day and it would've been on the patio two hours later. Or conversely, if he had been flipping through reviews and there was something to say, Hey, this person uses their umbrella, they're a professional entertainer and they've used it at 50 events this summer, he would've been like, got it. I know I've got what I need. But he was absolutely overwhelmed, analysis paralysis, couldn't make a decision and still hasn't bought a new stand for his umbrella.\n\nCole Heilborn (00:15:24): That's pretty funny considering how important in the grand scheme of things an umbrella stand is. And then if you extrapolate that to a product that actually has potentially lifesaving device, that's a huge decision to make. So you opened up another question that I did have that I was saving for later, but when it comes to reviews and Amazon reviews or customer reviews, we've always heard that reviews are vital. Are they though? You can just scroll forever and find, it's kind of like confirmation bias. You can find any response that you want to find about a product. When do reviews actually, when are they helpful or when are they no longer are you just stuck in the doom scroll?", "token_estimate": 446, "speakers": ["Becky Little", "Cole Heilborn"], "start_timestamp": "00:14:24", "end_timestamp": "00:15:24", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "920dd837-4cc7-47b3-8a29-450f0c20e6f4", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 10, "content": "Alex Willie (00:16:10): I think that's a great point, and I think that's something that I think at Expert Voice we kind of identified, right? How helpful is just, is it the 401st review that's going to make your mind up? Or at what point is that kind of critical mass? And I think at a core of it, it's not the quantity or the quantity of reviews that you're reviewing, it's the quality, right? Man, you might only see four or five reviews, but if you know who these individuals are, how they use the product, is it aligned with how you're going to use the product in the right environment and the right circumstances, all that, does that align to what they have to say? That's where the power comes, right? Understanding, man, I know that this individual has been hunting for the last 15 years of their life and this is the rifle that they swear by and it's the exact type of hunting that I'm going to be using. That's a powerful recommendation. As opposed to just seeing Becky l with a blank anonymous profile picture saying the color was really cool, or Yeah, it shipped really quick or was an easy process. It really comes down to I think a lot of those attributes of who is leaving the recommendations and does that align with how I'm going to use the product in my real life?\n\nCole Heilborn (00:17:29): And that obviously segues into a lot of the value that you guys provide, it sounds like where folks can go to your platform, they can find a product and they can actually get a firsthand account from an athlete or a real pro and hear their advice.", "token_estimate": 389, "speakers": ["Alex Willie", "Cole Heilborn"], "start_timestamp": "00:16:10", "end_timestamp": "00:17:29", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "d930130f-160e-42d7-8556-f49fd02b984f", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 11, "content": "Becky Little (00:17:45): And actually, let me clarify something, Cole, because not yet is it a consumer facing experience, but the way brands get those expert recommendations in front of more people is a piece of technology that we do offer them. So you can think about when you go visit a page and you see thousands of reviews, of course having the first dozen or so just verifies to the consumer that's a legit product and that other people are actually using it, right? And then to Alex's point, at what point have you read enough that you decide you've gotten what you need? What we offer brands is they're collecting expert reviews on our platform that they can then feature in an elevated manner on their product display pages. So it says these are select recommendations from experts, and when that widget that display, it appears on their page, it showcases their profile photo, their real name, their affiliation. So it says ski instructor, dog trainer, whole Foods associate expert for three years, and then provides their recommendation so that when the consumer is reading the reviews that appear on that product page, they can go read those or they can go look at the ones that are from verified credentialed experts that give them greater confidence about what to buy.", "token_estimate": 321, "speakers": ["Becky Little"], "start_timestamp": "00:17:45", "end_timestamp": "00:17:45", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "e40cb016-adf4-41e9-a3c3-6c2413245f94", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 12, "content": "Cole Heilborn (00:19:02): So alright, so if I'm going to buy a product, I'll use this microphone that I'm talking into. As an example, I recently upgraded my mic for the show and one of the first things I did was I went to Google and I think I typed best podcast microphone or something like that. And it gave me a whole list of options. And there's probably some article that I read that was 10 best microphones. I actually don't remember how I ended up on the one that I had actually, I think a friend ended up suggesting it. However, you've got me thinking about the idea of quantity versus quality when it comes to reviews and recommendations for products. If I went to Amazon and typed in podcast microphone, I would get hundreds of options and if I started reading the reviews, I wouldn't get anything valuable in helping me make my decision about what to purchase. (00:19:52): It seems like there's an opportunity for a site like Amazon to have, well basically what you guys do, experts giving specific reviews on their platform for products. If I went and I visited a microphone page and some of the top three recommendations were from let's say, I can't think of Joe Rogan, and he was like, I use this microphone exclusively and it kills it, I would be like, oh shoot, this is a quality product. Why doesn't a site like Amazon do that? It seems like it would help cut through all the noise and you wouldn't have to read 500 reviews if you could just know that one famous person uses it and they vouch for it.", "token_estimate": 380, "speakers": ["Cole Heilborn"], "start_timestamp": "00:19:02", "end_timestamp": "00:19:02", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "27118cbb-2131-497b-9b51-499b85dc85a2", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 13, "content": "Alex Willie (00:20:38): I'll give my 2 cents and I'd love to hear what Becky has to say too. So my role before I worked here, agency I in the agency, my guess is because there's a lot more money in having brands jockey for position and be able to pay to get some of that premium placement and pay the whole click-through rate and all of that, the pay per clicks side of digital marketing, I bet you it's much more a better revenue stream for Amazon to do that as opposed to a reseller commission or anything, what they get when they sell off of Amazon. So that would be my assumption as why Amazon might not be using a platform like Extra Voice yet. But I'd love to hear what Becky has to say too.\n\nBecky Little (00:21:25): Well, I would say they probably don't do it because they haven't built the infrastructure to be able to say, Hey, I know that this person is a verified podcast producer and how do I showcase that to other consumers? They have a database of a bazillion people who buy multiple times a year, they know our purchasing habits, but they don't know if I work in marketing, if I work in the tech space, if I work at Whole Foods or what, they know nothing about the rest of me. And so they have to invest in the technology, be able to say, okay, this person is who they say they are, and we all know that fake reviews are a huge problem on platforms like that. And then be able to showcase that to consumers so that they trust 'em. So Amazon, I would guess that's part of why they haven't invested in it yet. They're probably building it as I speak and trust me, we are thinking about how can we partner with Amazon and have them be using some of what we can offer.\n\nCole Heilborn (00:22:19): Interesting. How valuable is a expert's voice? If I'm going to an athlete and asking if I want to hear their opinion on a product, and I'm weighing that against all of the, the other information I have at my disposal, how valuable is that person's recommendation when considering everything out there? Is it 50% of the average person's decision making process?", "token_estimate": 518, "speakers": ["Alex Willie", "Becky Little", "Cole Heilborn"], "start_timestamp": "00:20:38", "end_timestamp": "00:22:19", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "35c76a3e-cabc-4ecf-846c-68054ec925fc", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 14, "content": "Becky Little (00:22:48): Well, one, I say McKinsey did a study years ago where they said two thirds of the consumer buying journey and decision process happens without the brand. So basically that means information they're gathering from other sources. So you can start from there. But then we've actually done studies on our own audience to understand the impact of the experts. So we've partnered with the Wharton School, we've partnered with Jonah Berger and Keller Fay, we've done our own optimization study. So we know that when an expert, someone who is trusted for advice about what to buy, if you use that as a very loose description that 82% of consumers are likely to buy or try based on that recommendation, pure just verbal recommendations. We know we've done studies with our retailers or people that are selling their products at retailer where we've been able to take their data of when you have people that have learned about your products, bought or tried them and are employed at that retailer and compared stores where they have people that have done that and people who have not, those stores on average are selling 23% more. So we know that we're having a big impact at retail. And then same thing for brands on their e-commerce channels, the ones that are using the recommendation display that features those experts, trusted expert recommendations in an elevated manner when they optimize it to make sure it's in the right place versus not having any expert reviews on their site. We've seen an average 40% increase in revenue on their sites. So it depends on the brand, what those percentages translate to, but the impact is significant.", "token_estimate": 416, "speakers": ["Becky Little"], "start_timestamp": "00:22:48", "end_timestamp": "00:22:48", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "c3a67a2b-b5c5-4fb5-9b13-fdb3a01b2ee4", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 15, "content": "Alex Willie (00:24:21): I think you answered your own question too, right? Cole, with the microphone, you did all this research, you did all these Google searches, and then you just went and asked your buddy, Hey, what mic do you use? And that was like, alright, let's do it. And I think that conversation changes a lot based on what type of purchases it is, right? Is it a brand new $10,000 mountain bike or is it a $200 sleeping pad? Right? The level of consideration byproduct varies a lot. And so to Becky's point, she just made, man, we got to make sure we we're doing the best we can in all these different channels at retail on e-com, all these different ways at word of mouth. So because where you're at in that consumer's buying journey about where that brand advocacy, where that product advocacy and where those recommendations come to the forefront are critical to make sure that those conversions happen.\n\nCole Heilborn (00:25:19): So knowing that information, having that data at your disposal, how do you look at what you guys are doing today and how do you look at what you should be doing or what you guys could be doing in the future to support that data?\n\nAlex Willie (00:25:34): That's a great question.\n\nBecky Little (00:25:36): You asking about our roadmap about what's coming next?\n\nCole Heilborn (00:25:41): Sure. I guess it's kind of an open-ended question, but what do you feel like is going to happen in the future knowing the data that we have today? You said 80% something like 80% of, I don't remember the exact statistic that you just said, but that blows my mind.", "token_estimate": 399, "speakers": ["Alex Willie", "Cole Heilborn", "Becky Little"], "start_timestamp": "00:24:21", "end_timestamp": "00:25:41", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "88c3a094-7d6a-4568-9d98-bd05ada2fedf", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 16, "content": "Becky Little (00:25:58): Well, so I think if you're a brand, you're hearing that, you're thinking how do I start shifting more of my investment into connecting with more of the people who are going to influence the consumer? If we know people have their ad blockers turned on, we know they aren't watching TV that has commercials on it anymore, how are you going to reach the consumer if they aren't listening to what a traditional paid brand advertising is? So I would think as a brand, you're thinking about how can I build a bigger community of people that's going to reach more people on my behalf? And that could be done at several levels. It doesn't necessarily mean that you have to go give everybody in your network a proform discount. It might mean that you say, okay, here's the people that are very important to me and they should get my product at 60, 70% off depending on the brand. (00:26:44): Maybe I'm going to give it to them if I can find the right pool of people. But there might be another level of people underneath there that maybe it's time to take your VIP customer group and at scale, figure out how to put them into your own community and maybe give them better inside access to your brand, tease them when new products are coming, give them the insights of how and why you built something and then let them know that every time they purchase, they get 15% off. And how stoked would they be and how more often, how much more often, how often would they be recommending your brand if they had an experience like that? If I was a brand, I'd be thinking about how do I activate those people who are really excited, passionate about what I'm doing and how can I do that at scale and then how can I track and measure it?", "token_estimate": 436, "speakers": ["Becky Little"], "start_timestamp": "00:25:58", "end_timestamp": "00:25:58", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "9897eb2a-d584-485f-8789-8b33c57298a8", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 17, "content": "Alex Willie (00:27:30): I think an interesting point you just made, Becky, is what can the brand do? I think especially this audience, these experts, these credentialed individuals, they want recognition. They want to have, how do I build a relationship with this brand? They don't want recognition from their peers or anything else like that. But how do I create this relationship with this brand to show I do know what I'm talking about. I do use your gear and this is the feedback that I have from it. I want to see that my voice is heard and I want you to see that me using this product in the wild. And if the brand is able to come in and give 'em a thumbs up, give 'em a like, right. You got to think that little micro, your brother-in-law, your sister-in-law, if they get a comment back from their favorite brand, from their favorite product, they're going to go tell everyone. (00:28:18): They're going to go, guess what? I was using this product and then the brand recognized me and they said, man, looks like a fun adventure, whatever. Creating those kind of spontaneous acts of advocacy are so powerful. And I think the smartest brands are doing that, especially the smaller brands that are kind of up and comers of how do we compete with the big dogs? You do little things like that. You get in front of the right people, you give 'em this catered experience, you make them feel valued, make 'em feel important, and man, you've got an army, a little cult following of these ambassadors, these advocates, whatever you want to call 'em, going out spreading the gospel of the brand about the product or whatever else it might be. But I think at a core of it, it's a lot of little things that add up and I think the smartest brands are doing all those little things.\n\nCole Heilborn (00:29:11): So if you could dissect those small ingredients that build that advocacy army, if you could pick a handful of them, what are the key elements that brands need to be doing to building their customers and advocates?", "token_estimate": 504, "speakers": ["Alex Willie", "Cole Heilborn"], "start_timestamp": "00:27:30", "end_timestamp": "00:29:11", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "22e0aac1-1698-44cd-ac54-bf68c5845201", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 18, "content": "Alex Willie (00:29:28): No. Well, I want to hear your thoughts too. From the conversations that I have every day with the brands, it's the recognition, it's the, Hey, if there's a positive review that comes in, man, go and say Love that you're having a good experience with this product. We're so happy. Do you mind if we use this content you just shared with us on our social channels? We'd love to display you using our product out in the wild, right? Man, even the negative reviews or the negative user generated content that comes in to say, man, I'm really bummed that you didn't have this experience. What can we do better? Or can we help you find the right product based on what you're trying to do? And I think those little things that kind of humanize the relationship between the brand, it's not just this big corporation that's shipping off these products to every little consumer, but if you can build that bond between consumer and brand, it's a pretty powerful thing. And especially with so much noise and so many competitor brands out there, if you can build that devotion, the dedication, the loyalty between consumer and brand, that's how you can tell that a brand's doing a good thing, right?", "token_estimate": 303, "speakers": ["Alex Willie"], "start_timestamp": "00:29:28", "end_timestamp": "00:29:28", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "deb51141-0ee9-446c-a9c0-cf1c6c3ec481", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 19, "content": "Becky Little (00:30:41): Yeah, and I'd break it down in its simplest form. When you say, where does a brand, what are the steps they're taking? It's ultimate essence. The core is who are the people that are influencing my consumers? Who are the people I need to connect with? I'm going to guess it's not all the Kim Kardashians of the world, so who are they? Where do they hang out? How am I going to connect with them, right? Do I plug into a platform like Expert Voice who might already have them as part of their member network or a platform like Expert Voice that helps me manage the people that I already do know that I can invite them there? Because then once I'm there, how do I make them better, stronger recommenders of my brand? And do I do that by simply giving them access to purchase at a discount? (00:31:22): Great. Step one, do I take it a step further and provide them some education about my brand? Awesome. Step two, do I really bring them into my fold and run campaigns where I can engage with them and start involve them in a conversation and make them feel like they're helping me to build my brand? Awesome. And then on the back end of that, so you've got your right people, you've figured out how to connect 'em, you figured out how to influence your influencers, and then how do I put what they're saying and what they're giving me as outputs to work in more places? Because when you engage and activate that audience, of course they're going to go speak about you probably twice as often or more as they did before, but they're also giving you outputs that the brand can use that are authentic, trusted recommendations, whether that's reviews, whether that's UGC, whether that's other quotes and feedback they've given you that help you strengthen your brand.", "token_estimate": 447, "speakers": ["Becky Little"], "start_timestamp": "00:30:41", "end_timestamp": "00:30:41", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "18ff5cac-cf4a-4d6b-8b3f-9feb6c8fed3d", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 20, "content": "Cole Heilborn (00:32:18): Alex, I love both of your answers, Alex, as you were talking though, what stood out to me is a simple act of recognition from a brand to a customer goes so far in that person then turning around and speaking positively about the brand, which seems, it's like, what's the secret sauce? It's like, oh, the secret sauce is really just super simple and being a personable brand or a personable person, which it seems too easy to be true.\n\nAlex Willie (00:32:57): Well, and it's funny, take customer service for example. No one wants to call customer service, but man, if you have a brand that just a customer service picks up a phone and handles it and does their job, you're like, whoa, that was the best experience ever. That was so easy to make a return, to have something, a warranty issue, whatever it might be. So as we look at these brands that we partner with that truly are doing the best, that are some of the best brands in the industry and are truly doing the best advocacy programs, they have this at a core of customer service first advocacy. We're building these spontaneous acts of advocacy across every department in their entire organization, sales, marketing, customer service. Everything that they do should be centered around the consumer and what the buying journey or that experience, because they know every little touch point that they get to have with consumer will then have a ripple effect of how they're going to speak about the brand, the product recommend. And so it's just kind of this full circle. If a brand's doing a handful of these things, you're going to get more people coming into that funnel. And if you're able to amplify that and scale that to Becky's earlier points, man, that's how you have some really successful brands getting the individuals that are talking about the brands and the products the best and the most educated.\n\nCole Heilborn (00:34:29): Who's doing it well in your opinion?", "token_estimate": 490, "speakers": ["Cole Heilborn", "Alex Willie"], "start_timestamp": "00:32:18", "end_timestamp": "00:34:29", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "ba0b59d9-b7cb-465c-9cd2-015665ccdc9b", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 21, "content": "Alex Willie (00:34:32): I've got a couple, I think there's a couple that really stick out to me. Vortex Optics is doing an incredible job of this. Vortex is doing things that they're flying out individuals, right? They're identifying individuals and giving them special experiences to be able to spread the goodness to show 'em, Hey, this is this experience. This is what we believe at a core. We want you to go and spread this out in your little circle. And so Vortex is an example that I think is just crushed it at on optics. I guess I'm biased. I work in the hunt fish tactical space, and so these are some brands that are coming to my head. Let's see. Those are a couple that are just really crushing it, but I know Becky's got a list of a handful as well.", "token_estimate": 191, "speakers": ["Alex Willie"], "start_timestamp": "00:34:32", "end_timestamp": "00:34:32", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "f24c2af5-c4e0-4e58-9f23-3b4324da81ad", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 22, "content": "Becky Little (00:35:24): Yeah, I'd say the one that comes top of mind to me, they're one of the customers I call every time we're rolling out new product, I'm like, Hey, are you interested in trying this? And they're absolutely, they're game on. Let me try. I want to stay ahead of the curve. I don't want to miss out. I'm happy to influence what you're building. And that's Ariat. And they've made huge leaps and bounds in the Western wear space, also building some, they're breaking into the health and the nurse practitioner, et cetera, medical space, but they are using the platform to help them identify their best ambassadors at retail. They were a retail driven brand, so they're using expert voice to make better recommenders on the retail sales floor, but they're using that information so that when their reps go into stores, they know who at that store is engaged, they go and call them out, they go and award them, make them feel special, incentivize them, bring them into their fold. And they've built this incredible retail army of advocates that has helped them gain significant ground and become a leader in the space. And they're in the platform every day. Anytime somebody posts something about their brand loads of photo, they're in there liking it, responding back, it gets its own private social network. So experts don't feel like they're littering their own social feed, but they know they can come here and share information with Ariat and T's going to see them and hear them and recognize them.\n\nCole Heilborn (00:36:49): Is there a particular platform that makes customers feel like they're acknowledged the most? If you're looking at something like a platform like Expert Voice or YouTube or Instagram, is there a platform that builds the most trust? I mean, maybe you guys are biased, maybe. Maybe it's obviously you guys.", "token_estimate": 463, "speakers": ["Becky Little", "Cole Heilborn"], "start_timestamp": "00:35:24", "end_timestamp": "00:36:49", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "a98edf6c-4c79-4a90-9528-00665cf33aa5", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 23, "content": "Alex Willie (00:37:10): I'm definitely biased. I think it's us. And the reason behind that is because there's so many different ways. There's so many different touch points. Being able to run specific campaigns to a certain audience, right? Calling out, Hey, sprout Associates, you guys matter to us because of X, Y, and z Whole Foods. Being able to run specific campaigns based on these individuals I think is incredibly powerful. And then of course, that's an input to what they're trying to do, but also being able to leverage those outputs of the consumer generated content that they're producing for 'em, right? Going in, leveraging those, commenting on those, the reviews, we've talked about these things before, but just all these different ways to kind of have that catered custom experience is really at a core what's valuable for building that relationship as opposed to having a generic YouTube video that touches every single consumer under the sun. I think they like to be recognized. They'd like to have that experience that they can't find anywhere else. You can't find on the website, you can't find on the YouTube channel, you can't find it. And the retail training, if you can have that specific custom experience, that goes a long way.\n\nBecky Little (00:38:24): And of course I'm biased, but when you think about social platforms and somebody who has a voice and an audience, they can go spew whatever they're going to spew, tag a brand and hope that the brand sees it and engages. But when they come to Expert Voice, it's a marketplace to engage with all the brands they care about the most. That's why they're here. That's why they come there. So they get access to purchase the products they need and to get more information when they need it. And the brands are there to listen to and connect with experts. So I mean, there's no other platform where they can get that experience for all the brands they care about the most.", "token_estimate": 487, "speakers": ["Alex Willie", "Becky Little"], "start_timestamp": "00:37:10", "end_timestamp": "00:38:24", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "dce22a30-87bd-4568-833a-cc540f6caf90", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 24, "content": "Alex Willie (00:39:01): And I think I'll add just to the audience portion of that, the experts, it's a different audience. These are the gear nerds, these are the gearhead. They're like the three of us here. I know we're all gearheads, right? We want to know every little thing there is about a product. And so the brand is able to speak differently to that individual as opposed to what their general broad marketing might need to be. So I think it gives this incredible opportunity for the brand to really get into the weeds, get granular about, let's hear from the designer, the product designer, about why they added this feature to that product, or let's hear from the CEO or founder of the core reasons of what drives the company to do what they do today. Getting a peek behind the current is incredibly powerful.", "token_estimate": 205, "speakers": ["Alex Willie"], "start_timestamp": "00:39:01", "end_timestamp": "00:39:01", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "dda60f4a-1ceb-4217-885b-ee43320f2eb4", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 25, "content": "Cole Heilborn (00:39:55): So this entire conversation, you've just got me thinking about the power of people and what a group of advocates can do for a brand. And I guess this is, maybe you guys probably think about this every day, but at least in my world, we do video and film production, and so often we're brought in with brands or agencies and we were part of our assets that we create are part of the digital marketing funnel or the sales process. And so we're out there creating assets for those brands. And so I don't often think about the customer and using the customer as your advocate, at least in this level of detail. And I'm thinking about a couple of years ago when I bought my mountain bike, I bought a specialized status and it was this bike. It is a bike that it was kind of like under the radar specialized, didn't really talk about it, it was direct at the time. (00:40:56): I think it still is. It was direct to retail and there was only a few articles online that would talk about it, but there was kind of this underground movement of this new bike that had hit the store, the shop, and it was very affordable. It was super specked out and for bang for buck, it was a really solid bike. And I am thinking about that experience in myself purchasing that bike and seeing a friend who was riding that bike and being like, where'd you get that? And he's like, oh, it's kind of this, not exclusive, but it's kind of like this insider track bike that's just come out and you got to go talk to this specific bike shop if you want to find one. And the entire experience that I had purchasing this bike was, I think I looked at one Pink bike article, but everything else was from my friend on the hill to the bike, the bike rep down at the store, and now I'm a huge advocate for the bike. I see people on the trail and they're like, what is that? And they're like, oh, this is the status. And they're like, oh, I've heard about that. And I don't know. I'm thinking, what if you could design an entire product marketing experience solely through word of mouth, solely through customers and advocates, and could you just eliminate entirely the digital marketing side of it and create this underground swell of enthusiasm for a product?", "token_estimate": 562, "speakers": ["Cole Heilborn"], "start_timestamp": "00:39:55", "end_timestamp": "00:39:55", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "7abd26ec-9c0d-4016-a9ec-f6e3fabd00b6", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 26, "content": "Alex Willie (00:42:24): Who led the charge for that status? It was Lucas Shaw. It was Walker Shaw. It was the guys that were racing the Pro GRTs at the time. The other bike was the demo that was their flag flagship downhill bike. So everyone was going, oh, if I'm going to get a downhill bike from specialized, I'm going to get the demo. But they were trying to, how do we position this other bike as just as credible as the demo, just potentially maybe for the budget conscious or for someone that doesn't need a full on World Cup down a race bike. And so putting my lens on now in terms, what did specialized do? What was that 10 years ago, they had the people maybe not in the World Cup. I know they had a couple guys in the World Cup racing it, but every national round I knew I was racing 'em, right? (00:43:15): Lucas Shaw, these guys would come out on the status and everyone was scratching their head, why are they having 'em on a status instead of a demo? And sure enough, they're crushing it. And so you're like, that is how you build credibility, but you get those kind of micro influencers to be able to add some legs and some muscle to the product. I think to your point, it adds a lot of that underground kind of movement. How do you build the hype train and get it going, get other people talking about it? And as you saw firsthand about what bike's in your garage right now, it was effective.", "token_estimate": 352, "speakers": ["Alex Willie"], "start_timestamp": "00:42:24", "end_timestamp": "00:42:24", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "854376b0-0f58-4d96-8d68-081f8d419e67", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 27, "content": "Becky Little (00:43:52): And I'm dumbfounded. It's amazing because one of the projects I've gotten to work on in the last couple of years is helping brands with a better product launch program and how many brands put all this effort into researching and building a product, and then they're so excited to get it to market, they just dump it in the marketplace and then launch an advertising campaign and you're like, gosh, you have missed such an opportunity to build that underground swell of energy and excitement and also a little insider knowledge from the brand to make sure it really is being received like you thought it would before you dump all the rest of your marketing dollars against it. If you could curate this audience of the people who are going to influence your consumer and get it into their hands before everyone else so that they start talking about it and get really excited about it, how amazing is that for a brand? And there's programs out there depending on what kinds of things you're looking for, but there's an opportunity I think for brands to do so much more to have the status type of success,\n\nAlex Willie (00:44:53): Pun pun unintended,\n\nBecky Little (00:44:57): That was totally not intended.\n\nCole Heilborn (00:45:01): Why should in today's world or brands or just pumping out content and talking about themselves, why should consumers continue to trust what brands are saying about themselves?", "token_estimate": 358, "speakers": ["Becky Little", "Alex Willie", "Cole Heilborn"], "start_timestamp": "00:43:52", "end_timestamp": "00:45:01", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "81ba11c6-b122-4d71-8728-4a89bf9dc79d", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 28, "content": "Alex Willie (00:45:15): No, that's an interesting question, right? No one can say what the brand is saying is not impactful. It is, right? But I think some of the most, if you think through, and I can't think of any specific marketing examples right now, but I've been influenced in the sense of if a marketer or a brand is saying, go ask X, Y, and Z, or this is what this person has a say, snowbird, right? They did a cool marketing campaign where they advertised a one star review too steep, too much powder wasn't fun. Let others speak on your behalf. And I think it goes, it's more powerful than Snowbird saying, this is how many inches of snow we get each winter. This is how many runs we have open, this is X, Y, and Z. But I think those have been pretty powerful or pretty powerful campaigns that I've seen.\n\nBecky Little (00:46:15): And I think the brands are always going to have a voice. They're always going to have a role in the consumer decision. I'm not saying advertising needs to go away. There's a role for creating awareness, but I think what consumers are going to be looking to brands for are the tech specs. They want to make sure that they understand how big the frame is that what kind of components are on the bike or whatever it is that you're researching and looking for. But when it comes to actually understanding who it's a fit for and why someone might use it, they're going to want to lean on people with that firsthand experience, even if that firsthand experience was provided by the brand. And even what they're saying it was education was provided by the brand just by virtue of sitting and having conversations with you today. Now I trust what you have to say about podcast equipment over anything. I'll read anywhere else.\n\nCole Heilborn (00:47:01): Right. Interesting. I'm curious how bias affects people's reviews and people's reception of reviews. Is that something you guys talk about? Is that something that is discussed or is that kind of a non-factor", "token_estimate": 499, "speakers": ["Alex Willie", "Becky Little", "Cole Heilborn"], "start_timestamp": "00:45:15", "end_timestamp": "00:47:01", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "fde87c2d-ee1c-46ca-b3fa-0846e1b78d34", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 29, "content": "Alex Willie (00:47:26): Bias by, I'm to think of in my day to day, a potential bias could be who this individual is. For example, if you're looking for your next pair of skis and you hear what someone from the military or law enforcement has to say, maybe you're not putting the same weight as you might as a ski instructor or snowboard instructor or an avalanche, an area two instructor, whatever it might be. That's where my head goes when you're talking about bias of who is this person and why does their opinion matter? I think that goes a long way in terms of the credibility. But to our earlier question at the beginning of the podcast, right? Why does it matter? Is it the 401st review or is it who is saying what? I think it just ties back to that as to kind of alleviate some of that bias. I think just understanding who that person is and how they use the product will help navigate away from some of those potential hangups.\n\nCole Heilborn (00:48:33): And I guess maybe to further explore my own question, when I'm thinking about bias, we talked about the sponsored post, and that inherently creates bias, whether you're aware of it or not. And I guess I'm thinking about it from the athlete perspective. A lot of brands have athletes, and one of the jobs of athletes is to get out there and talk about the product and share the product on the hill. Or if the local Craig do athletes of a brand, how do they stack up when it compares to their voice validating products? Is there bias that is a factor in the purchasing process when athletes are the ambassador? I realize I've just kind of clarified my question more for you, Alex, but took me two questions to get to the question I was really trying to ask.", "token_estimate": 430, "speakers": ["Alex Willie", "Cole Heilborn"], "start_timestamp": "00:47:26", "end_timestamp": "00:48:33", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "05f06832-c4ed-4c98-9b70-7ebdf1a7456e", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 30, "content": "Alex Willie (00:49:28): Thanks, that's helpful. I'll put myself now in the consumer shoes, if I were to see a Joey Schuler doing an Instagram post with a competitive cyclist, hashtag sponsored, right? As a consumer, yeah, I understand he's doing this cool adventure. He is got this amazing content, he's posting it. Does that make me want to go buy stuff from competitive cyclists? Maybe not. I love Joey and him and I are good friends and he's producing amazing stuff. But I think as an athlete, if I were to see another buddy of mine that's still racing for sake of name for Shane Leslie, if he's out racing and he's being a hundred percent transparent about, man, this is what happened this weekend. I had Arai failure. I'm a Shram athlete, Orano athlete, and sharing the highs and lows of, it's not all just perfect. I think as a consumer I resonate more with that. (00:50:29): Like, oh, well that makes sense about why this broke and the circumstances that this was in to make that failure happen. Because he says, that doesn't mean I'll never buy a shram derailer again, but I'm thinking like, oh, well man, he was using in this use case every other post. He's stoked on how smooth it is. And so as a consumer, it helps getting both sides of the story a little bit. And I think we see the same thing with product reviews. A consumer will get the same amount of info and data and kind of purchase power from a negative review as they do from a positive review, if not more. And I think some smart brands are displaying these negative reviews in addition to the positive reviews. You need to have that transparency. As a consumer, I like to see it. I want to see why it didn't work for this person. And I think it helps alleviate some of the bias that you were talking about of not just hashtag sponsored, not just getting all this free stuff and everything, unicorns and rainbows, because I got it for free. So that's just my 2 cents.", "token_estimate": 485, "speakers": ["Alex Willie"], "start_timestamp": "00:49:28", "end_timestamp": "00:49:28", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "9727e862-b1d9-43a0-bee6-935d310cc2ca", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 31, "content": "Cole Heilborn (00:51:39): Yeah. Interesting. So what does the future look like if consumers are smarter, getting smarter, and the value of word of mouth is that much stronger? What does that look like for the future of Expert Voice? How are you guys adapting? How are you growing and evolving?\n\nBecky Little (00:51:58): I think for Expert Voice, we're constantly thinking about how can we help brands get recommendations from the people consumers trust for advice in more places? So we've been doing it in the retail setting for a long time. We've been doing it through word of mouth, through products, heating to pros for a long time. We launched the ability to influence what people are seeing, experiencing the e-commerce space, and we're continue to explore how do we integrate that further? We have a display they offer, but we let them sync or they can sync over all of their expert recommendations through review providers like Bazaar Voice and Yacht Post, so that at least they know the Empower reviews that in their stream of customer reviews, there are going to be credible reviews featured there. Where do we go next to help enhance that experience? Experts are posting pictures and content on the platform, and how can we make it easier for brands to share? (00:52:51): We just released this fall. The ability to make that easier for them to download those. Some of them are pre-formatted so they can get not just the image, the expert shares, but the picture of the product that they're using, and then an actual picture of the expert's profile. So when they go to share that online, they can share all of the background behind it. How can we make that more seamless for brands currently, experts, when they share inside the platform, it's a gated experience, but how can we make it easier for experts that are sharing all this great knowledge for them to share it on a brand's behalf? And then I think we're going to see what comes next. What's the latest platform that comes about next that brands want to be partaking in? We didn't collect video on our platform until just this summer, and now experts can post video on the platform, which we all know video's not going anywhere anytime soon. So how can we make that better and easier for brands to capitalize on? And I think also, how do we keep making the experience? How do we keep making sure that the expert experience is top notch so that there aren't other places they want to go, that they do keep expert voice top of mind for where they go to connect with brands.", "token_estimate": 635, "speakers": ["Cole Heilborn", "Becky Little"], "start_timestamp": "00:51:39", "end_timestamp": "00:51:58", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "c2348f37-e05c-4964-ad31-8c2190d2db9f", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 32, "content": "Alex Willie (00:54:03): Yeah, I think that last point is so important. How do we continue to get the right people in the platform and making sure that we're keeping up with that, right? That's something we put such a focus and emphasis on, is making sure not only the correct people are in, but man every year, are we re-verifying, making sure that credential is still valid, that they're still at that retail store. Are they still worthy to have this kind of experience that these brands are wanting to create with these individuals? So super excited for what's to come Maddox or voice in the next year and a half. So I think, yeah, we've got a bright future ahead of us,\n\nBecky Little (00:54:44): And I would say as a brand, if you're thinking about how do I do this better? If you're just thinking about pro programs and how do I get more people wearing my stuff and talking about my stuff or using my stuff, you could be getting so much more out of that investment. So how do you make sure your dollars are limited? Right? Margins are thin. So if you're going to go and bother to seed product to people, make sure you're getting 'em in the right hands and make sure you're getting the most from that, that you're getting feedback from 'em and outputs that the brand can use, and that you have the visibility to know what they're saying about your products. It's not just going out into the void.\n\nCole Heilborn (00:55:18): Yeah. For both of you, two side question. What's the biggest opportunity for brands in the future and what's of the biggest obstacles or challenges that they have to navigate surrounding everything we've discussed today?", "token_estimate": 412, "speakers": ["Alex Willie", "Becky Little", "Cole Heilborn"], "start_timestamp": "00:54:03", "end_timestamp": "00:55:18", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "10478a57-166e-461c-b33a-83c01fd65120", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 33, "content": "Alex Willie (00:55:36): I think I'll start with the last one. The biggest obstacle. I think more and more brands are figuring this out. I think they're realizing that this is how we speak to consumers now, right? Consumers are getting smarter. How do I stand out? And so I think before and even what, a couple years ago, you can have a handful of brands in each category that are doing these things really well. And they're the clear market leaders because they're creating these experiences, they're having these brain advocates speak on their behalf, and that's how they're having the growth. (00:56:11): And then something that I'm super excited about is just to continue to grow our platform offering. I think the last three years on Expert Voice have been incredible in terms of what our product team has designed, and they've given us such a great platform to continue to optimize and refine moving forward that, I mean, we're small enough and agile enough that every little feedback we get from a client, it will legit go to the lead product designer for that product and be like, yeah, maybe next quarter that'll be something that will be live. So just small things like optimizing. To Becky's point about videos, a brand probably is like, I would love to be able to capture video recommendations. Okay, we'll build it. And so I think we're in a really unique position as a business to be able to do all those little things that brands are requesting and see a tremendous amount of value in.", "token_estimate": 375, "speakers": ["Alex Willie"], "start_timestamp": "00:55:36", "end_timestamp": "00:55:36", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "d5996780-7c6b-45f7-baac-badedaacbbc3", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 34, "content": "Becky Little (00:57:09): I think brands' biggest opportunity is this idea of, I mean, community marketing is something that you hear out in the marketplace all the time now how are brands building communities? And I think the brands that are going to win are the brands that are really thoughtful about how they're doing it and that they're building customized community. That's not just a one size fits all approach. How ecstatic would I be to be in a customer community of female at home, passionate cooks where I got to connect with others? Maybe it might need to be female, but whatever the audience is that you could fit your niche customer approach and that that's going to just build you twice as much loyalty and advocacy as anything else you could do versus feeling like you're just part of some anonymous big group. I think the biggest challenge for brands is figuring out how do they prioritize that initiative and how do they put people leading those charges? (00:58:03): They're so ingrained of how they've always been doing something, their tactics that they're pretty sure are winning or maybe are winning and that they have to reprioritize the resources to invest in building relationships. That doesn't happen overnight. I think that's probably one of our biggest lessons we've learned as we've been rolling out some of these products is that it's not like you just flip a switch and magic happens tomorrow, right? It is a long-term game where the brand has to invest the time and the energy into cultivating and fostering relationships. And that doesn't mean they have to call me every morning and say, Hey, good morning, how are you? But that they do have to have a consistent strategy to keep people engaged and excited and interested in what they're doing.", "token_estimate": 445, "speakers": ["Becky Little"], "start_timestamp": "00:57:09", "end_timestamp": "00:57:09", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "38aa9bff-3578-402b-a592-ef2447d049e4", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 35, "content": "Cole Heilborn (00:58:43): Yeah. Yeah. Well, I said it earlier, but all of this sounds so simple, but it's not. And there's a lot behind the scenes and there's so many different ways to break all this apart, but at its core, we all just care what our friends think about whatever they're using, and that's the recommendation that seems to weigh the strongest. I mean, yeah, actually that sounds kind of nice, not having to go online to find a review or find feedback. If you could just always have a friend who knew the best scoop on whatever you're trying to purchase, whatever product you're trying to find, but that's not the reality and you need resources out there, and it sounds like that's what you guys provide. And then, and it sounds like there's a lot of opportunity.\n\nBecky Little (00:59:38): We think, so we're really excited about it,\n\nAlex Willie (00:59:42): And it's fun. It's a fun problem to solve. You're able to get creative with it. You're able to try different things. And to be an earlier point about being agile as a business, the community tool, super exciting. This product sampling campaign tool, super exciting. Being able to get product in the hands of individuals before we go to market with that, right? Let's get feedback. Let's get user generated content, let's get recommendations so we know what that's going to look like moving forward. I just think there's so much power in that it gets us fired up in the morning and it's fun to go to work, so there's no complaints from this side of the Zoom box.\n\nBecky Little (01:00:23): And it's fun to connect with brands to see their authentic reactions when they're like, oh my gosh, if I could just find one person that looks like this, I would give them my product. You're like, well, you've got 15 of them right over there. For a brand to say, gosh, I had this community of retail sales associates from the pet store, and now I have frontline inside of what's happening on the store floor and how my displays are set up. I couldn't do that at scale before. It is just so fun to see how brands are gathering new insights, learnings, and applying them to make their business better.", "token_estimate": 540, "speakers": ["Cole Heilborn", "Becky Little", "Alex Willie"], "start_timestamp": "00:58:43", "end_timestamp": "01:00:23", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "81e8c791-333b-4fa2-90bc-dfbfedb2c7df", "episode_id": "380ad7c4-5f33-48eb-a50a-66f5c54ab0c6", "cms_item_id": "68225dfc7bb476527f8c489f", "chunk_index": 36, "content": "Cole Heilborn (01:01:04): Well, Alex and Becky, I want to thank you for taking the time to chat. If folks have questions about Expert Voice, about any of the services that you offer, where can people go to either get connected with the company or with you both personally?\n\nBecky Little (01:01:18): I know we're both on LinkedIn, so feel free to hit us up there, but expert voice.com, there's a Let's Talk button and that'll get you to the right place. And if you're an expert too, if you're thinking, Hey, I'm somebody who should be in that network, same thing. They'll take you through the onboarding process. You'll have a chance to upload what we call your affiliation or your credentials to say, this is why I deserve insider access, and we're happy to welcome you to the platform.\n\nCole Heilborn (01:01:46): Okay, awesome.\n\nAlex Willie (01:01:48): And I'm happy to, I bet you, I don't want to speak for Becky too, but man, any direct questions too, man, hit me up on LinkedIn. I'm more than happy to dive in, set up a phone call with a potential brand experts helping them get through the funnel. It doesn't matter. Becky and I are happy to be a resource for folks.\n\nCole Heilborn (01:02:06): Awesome. Well, thank you both for taking the time to chat. This has got me some new ideas, new topics to think about for this week. So I want to thank you again for taking the time and sharing a little bit of your guys' world. There's a lot of exciting things.\n\nBecky Little (01:02:20): Thanks for having us, Colt. It's fun to hear the stories you share with our community, so look forward to it.\n\nCole Heilborn (01:02:25): Yeah,\n\nAlex Willie (01:02:25): Thanks so much, Cole. It was a pleasure.\n\nCole Heilborn (01:02:28): All right. Have a good rest of your day. Take care. Okay, you as well. We'll see you.", "token_estimate": 452, "speakers": ["Cole Heilborn", "Becky Little", "Alex Willie"], "start_timestamp": "01:01:04", "end_timestamp": "01:02:28", "podcast_index": 122, "episode_name": "EP 122: How to Build Loyal and True Fans | Alex Willie & Becky Lyttle | ExpertVoice", "slug": "ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "web_url": "https://www.portsidepro.com/podcast-feed/ep-122-how-to-build-loyal-and-true-fans-alex-willie-becky-lyttle-expertvoice", "guest_name": "Alex Willie and Becky Lyttle", "guest_title": null, "categories": ["brand"], "short_description": "On this episode of the show, we have two guests! Alex Willie and Becky Lyttle from ExpertVoice join us to tell us how to build loyal and true fans, the importance of brand advocacy, and building your brand community.", "podcast_length": "1:04"}, {"id": "ef2099ab-7629-4880-b88e-4802987d79a3", "episode_id": "d3aec1b6-3937-4ab3-9322-115d294e235f", "cms_item_id": "68225dfc7bb476527f8c4922", "chunk_index": 0, "content": "Matt Powell (00:00.27): I would tell you the underlying part of the business is actually pretty healthy. But there are issues that we're facing around inventory, around product, around the way we bring product to market, the way we address our customers, the total available customer base that are making us not so good right now. So it was a tough year. I think 24 is going to be a tough year. But I do again feel the underlying piece of the business is still solid. ‍\n\nCole Heilborn (00:34.606): Welcome to the Backcountry Marketing podcast. I'm your host, Cole Heilborn. On this podcast, you'll hear from leaders in the outdoor marketing industry discuss the gritty details of their work, as well as the latest challenges and lessons they're learning along the way. If you want to hone your craft and become a stronger marketer, then this podcast is for you. ‍ This podcast is produced by Port Side Productions, an outdoor film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. Today, I'm sitting down with Matt Powell. Matt, you've been in the industry for 51 years now, all across the retail world. But today, you currently work with SpurWink as an advisor. You study data and trends and help all of us make sense of where the industry is going, what's changing, what's evolving. And you've got some really fascinating insights to share with us today. So welcome to the show. ‍ Matt Powell Thanks very much for having me. I'm excited to do this. ‍ Cole Heilborn So if you could give us an opening statement, I'm going to limit you to 60 seconds. From your perspective, what is the state of our industry today? ‍ Matt Powell I would tell you, the underlying part of the business is actually pretty healthy. But there are issues that we're facing around inventory, around product, around the way we bring the product to market, the way we address our customers and the total available customer base that are making us not so good right now. So it was a tough year. I think 24 is going to be a tough year. But I do, again, feel the underlying piece of the business is still solid. ‍ Cole Heilborn Well, I'm excited to dive into this. I think there's a lot of talk out there about the state of the industry. Some people are very pessimistic, some are incredibly optimistic. And I'm excited to, as I said, kind of to dig into this and evaluate what are the trends that you're noticing. What are the opportunities that exist that maybe we aren't considering? But before we go there, I'd love to back up a little bit. And 51 years of retail experience is, I can only imagine the amount of stories that you have, but I'd love if you could give us kind of the quick background on yourself. Kind of what your expertise is and some of the work that you've done ‍ Matt Powell Yeah, so I started out my career in the department store business actually I spent many years and almost 20 years with one retailer which in today's world is completely unheard of and in the early 90s there was sort of an implosion around the department store industry that created giant retailers like Macy's and A whole lot of us got to find something new to do I then had crossed over to the sports world. I worked for Sport Mart in Chicago, which at the time was the largest big box sporting goods retailer in the country, later acquired by Sports Authority and now out of business. I left there, went to work for a sneaker superstore. We carried 1,500 styles of sneakers and I don't recommend anybody do that either. That company was sold and they wanted some of us to go to Alabama and I didn't see myself in Alabama so I stepped away. I worked for Models for a year. I tried consulting for a year and failed horribly at it and then I got a call to take what was the second coolest job I had after this one. I was a dot com in the early days of the dot com business called MVP.com that was started by Michael Jordan, John Elway, and Wayne Gretzky. And I got to meet those guys who work with them. But like a lot of early .coms, that one burned down. And I tried my hand at consulting again, and I had met a couple of hedge fund managers when I was at SportMart, who would call me periodically to get my opinion on what was happening in the sports industry. And when I said I was consulting, they said, hey, we'll pay you to do research. So. 23, 24 years later, I'm still doing research on the industry. So I was working for myself in the very beginning. I had an affiliation with Sports One Source, which publishes Sporting Goods Business Magazine. I left there 10 years ago, went to work for NPD, which is a large market research firm covering all of sports and that company was sold and then merged with another company I left a year ago and started my own thing. And I'm also having an affiliation with a group called BCE Consulting, which is where I'm doing most of my work. And it's been a lot of fun. We're doing strategy work, merchandising work, five -year plan evaluations. We're doing some very specific market sizing kinds of work. So it's been a wide range, but really my goal was to do fun and interesting things to give back to the industry because the industry's been so good to me and to take some control over whatever my final years, and that's plural years, in the industry. I'm not going anywhere yet. I'm having too much fun. So I told somebody the other day, as long as I can remember people's names and phone numbers, I'll be fine. ‍ Cole Heilborn So when you talk about research, can you share a little more in terms of where you're finding information, what sort of information are you pulling and how are you using that to help folks? Just to provide a little context to what that means for you and your world. ‍ Matt Powell Well, when I was at NPD and prior, I actually had POS sales data that would help inform my decision making. I no longer have access to that. There are public statements that are out there from brands and retailers. Sirkana, who replaced NPD is now putting out some information so that it's in the public domain so I have access to that. There are other sources out that provide again public statements on their data and then I'm talking to a lot of brands and retailers all the time and so anecdotally I can piece together what's happening in the industry and you know I've been to this rodeo more than once so I see things coming around again that happened before. And nothing ever happens the same way twice, but there are always parallels to that. So it's really very informal today. But I talk to so many people that I really feel very well informed about what's happening in the industry. ‍ Cole Heilborn So it's not a surprise, but I think everyone understands kind of the basics of the COVID boom and then bust and kind of the downward spiral that we've been in. And that's a really common, you know, that's a common tale that everyone references. I'm curious though if you can kind of shed a little more light, maybe a little more nuance into what happened to put us where we are today, but beyond maybe just the surface-level explanation as to what 2024 looks like and how we got here. ‍ Matt Powell Sure. Well, so it, I mean, I think there's some really good things that happened to the industry during COVID. People felt safer outside. I think people wanted to get out of their houses. I think they were feeling claustrophobic, wanted to get out and recreate. And so there was a huge surge in outdoor activity that happened. And that's continued. Perhaps we're not surging, but they've remained at very high levels. I live on the Spurwink River, hence the name of my company. And there's a tremendous amount of recreation that happens on this river. Stand-up paddle, kayak of all sorts, swimming, some small watercraft. So you could see it just looking out my window that the world had changed. And on the trails and lanes around where I live, lots of people out walking, hiking, again, trying to get outside where they felt safer and to recreate. Big positive there. That caused a surge in business. The stimulus money that went out, caused a big surge in business. And it was initially a very good thing, but it's become a problem in that if you bought a big ticket item during the pandemic, a kayak, a stand-up paddleboard, a bicycle, a fire pit, you don't need another one unless you broke it or you didn't like it and wanted to get something different. So there was a huge surge during the pandemic and we've come down from that now, but we're not back to 2019 levels. And so there's more good news for the industry that longer view, we can say, hey, you know what, we're still in a pretty good place, although we are giving some of those gains back. On the negative side, a couple of things. I think the shortages that happened during the pandemic didn't give the consumer a full breadth of products to buy. And if they were in a fever to buy something, that perhaps they bought something that was above their skill level or above their needs. And when they tried to use it, they found that they couldn't use it because they didn't know how to use it. They weren't an experienced user. You know, I think some retailers oversold people product just to, to make the sale. And again, I think there's that hurt the industry. I think people who were oversold lost interest very quickly said, oh, this isn't for me, I can't do this. And so they abandoned it altogether. I have no data on this, but my sense is the secondary market has flooded with products that people tried during the pandemic and then decided they didn't want to use. And by the way, if you live in an apartment, what do you do with a stand-up paddleboard? What do you do with a kayak? I mean, you can't leave it on top of your car all year long. Well, maybe you can, but you know, there's no place to store it. So now what do I do with it? So a whole lot of things happen. ‍ Cole Heilborn I'm curious if you have any data or anything that expresses kind of the state of our industry. So I think people would say, well, it seems like there's there's kind of conflicting messages. Some people would say things are in a downward spiral. There is obviously the the report that came out last November about the industry being a trillion-dollar industry. And there's a lot of nuance there, certainly. So it seems like there's conflicting messages about how the industry is performing overall. What insight can you provide that might help us better understand what's happening? Well, I think we can look to the public companies, the large big boys out there, REIs and the VFs and so forth, Wolverine to some extent, and get a good read through on at least a part of the market. And pretty much everybody's put up some pretty disastrous numbers. That doesn't mean there aren't bright spots out there. And I think we're going to find that when we look at it, that some small retailers have done well, maybe even some larger retailers have done pretty well. Big Five, who we don't really think of as an outdoor retailer, but has actually a fairly significant portion of their business in outdoor, had a really tough quarter of California before all the snow came to California. I guess, from public companies would tell us that the business is not very good. But again, that doesn't mean there aren't bright spots. And there's another, actually there's another interesting element that I think says that probably the future is going to be better but more challenging, and that is the number of companies who are getting into the outdoor business. And I put my fake quotation marks up with that. You know, who are adding outdoor products to their assortment. Maybe they're using private label to bring in outerwear and fleece and plaid shirts and so forth. And I've had a lot of calls over the last two or three years from people with money saying, how do I get into this business? Where are the openings for me to get into this business? So the space is becoming more crowded, particularly on the apparel and footwear side. The blending of outdoor and athletic, another piece of the story here. And ultimately, I see those as good things for the industry. Anytime we're forced to be more competitive, we get better. So these are not structural issues that are putting up roadblocks into us. It's more competition. We're saying, hey, we've got to get better at what we do. So I see that as a potential bright spot for the industry. ‍ Cole Heilborn So this is what I've always wondered. How much of the decline is inflated because there was a massive surge? If we were still on track with the same growth numbers that we had in 18 and 19, would we still be in a decline, quote unquote, now? Or how much of, OK. ‍ Matt Powell No, I think what we're doing is giving back some of the business that was artificially stimulated, which was, I guess, the intent, if you will. But, you know, again, and again, people bought things they didn't need. People bought things that they don't know how to use. All of those things are weighing down on us. But, you know, if you bought a if you bought a car during the pandemic, you don't need the car right now. So it it there is definitely some give back here. But, you know, if we were at the more normalized rate, we wouldn't actually probably be as high volume numbers that we're actually at today. Are there other industries that are facing a similar trajectory or is outdoor unique in some way? No, I mean, the bike business is another one that's very, very much a parallel here. The fitness equipment business, which was terrible before the pandemic. When the pandemic hit, people couldn't go to gyms, so they went out and bought a bunch of equipment. That industry is giving back those gains as well. And frankly, even the sneaker business is not great because people filled up their closets with sneakers and you don't need another. And by the way, the marketplace hasn't brought anything new out. And maybe that's another layer on the conversation here is that, particularly in the sneaker industry, the big brands really shut down their innovation engines. And there's not a lot new out there. We look really old and tired on the floors and in sneaker stores as an example. So, you know, one of the ways we're going to get out of this is by fresh products, fresh ideas. You know, and I think embracing the family as a really viable channel here, something that the outdoor industry has kind of shunned. You know, we saw a lot of people trying to take their home into their backyard during the pandemic, again, to extend their homes and sales of things like pop -up shelters and grills and outdoor furniture and fire pits all went off the charts during the pandemic. Now, again, if you bought a fire pit or a pop-up shelter, you probably don't need another one right now, but people are outside more. And so I think that there's an opportunity to extend that as well. But I think the industry has really focused far too much on themselves as the end consumer and not really look to the much bigger marketplace, which is the family side of Outdoors. ‍ Cole Heilborn Yeah, tell me more about that. I mean, the industry is kind of notorious for trying to remain core. I think there's often been this struggle of what is outdoor? You know, what, what do we, what do we allow? What do we accept? And there's a lot of, um, I have a lot of questions about why do we put these parameters on ourselves as an ego thing? Is it a, um, you know, is it just a, are we just being gatekeepers for the sake of trying to keep our, our mountains and our places pristine? Um, but as, as you mentioned on our previous call, there's so much opportunity outside of the core and there's this struggle internal and external, I think to really like allow ourselves to embrace, you know, what is considered non-core, if you will. Can you share more about your thoughts here? ‍ Matt Powell Yeah, well, I look at the industry has always been a club, a clique, however, you want to mean girls, however, you want to describe that. But, you know, the outdoor retailer show was always people who were standing in the aisles talking about what are their latest exploits were. And that's fine. If that's what you want to be as an industry, that's fine. But you have to understand that it's finite. And it means that there are going to be limits to how much you can grow. And there are so many public companies in our space today who have to grow to satisfy the stock market and their shareholders that they have to have growth. And so to some extent, being small and I'll use the word elitist or exclusive, it argues against growth. So if you're happy being a small company, a big fish in a small pond, good for you. But you're never going to be Nike. And everybody has these ideas that they could be a $50 billion brand. And if you're going to be $50 billion, you've got to do a lot of more broad-based kinds of productsAnd again, there are people who are recreating today who weren't doing it before, but they're not doing a three-week pack -in. They're going out for an hour or two hours or driving to a state park and having a picnic. And that's part of the outdoor world as well. And I don't think that threatens the core in any way. And a lot of the products the core uses will never be used by this consumer. But I think everybody's after the same ultimate goal, which is to get outside and have fun and be healthy. ‍ Cole Heilborn Yeah, what's the risk then? Like, why is the industry hesitant? ‍ Matt Powell Well, I mean, part of it is that the industry is an echo chamber. OK, and so they they're talking to themselves about topics that they concern themselves with. And they don't really understand the broader market. I remember I did an address to the OR show 10, maybe 12 years ago, a study the National Sporting Association did a study on Hispanics and the outdoor business and noted that Hispanics do things as families. They like fishing as in recreation. I don't remember all the points of it, but the big point of the white paper was there's a huge business opportunity the industry's overlooking. And so the industry talks about being more inclusive, but it tends to be more inclusive doing the core stuff as opposed to being inclusive doing the more family-oriented stuff. So it's not sexy It's not dangerous. It's not it's not elitist it but there's that's where the business is for in that example, like how big is the opportunity the Hispanic population represents, do you know I? Don't recall I think we'd have to dig up that white paper again, but there was a significant economic opportunity around that business so You know, I think that's really the question I think the industry needs to confront is, are we willing to not be so core? Are we willing to have a bigger tent to let people come in and be part of this industry? How do we do that? How do we encourage people to get outside and support all the things that this industry supports? ‍ Cole Heilborn I mean, that's a conversation that we've had many times on this show. Folks are asking themselves, how do we be how do we reflect our core? How do we honor them and, you know, who we were, where our brand started, our foundation, but then how do we bring in people who don't look like that, who aren't, you know, somebody and accomplishing FKTs and all of the ridiculous things that folks do. So there are conversations that are happening, but what do you think, what will it take for things to really change, to go from beyond conversations to action to actually making an effort. ‍ Matt Powell Well, look, I think if a retailer is successful and is able to execute against this, I think that sends a message to the rest of the industry. I think if you look at a retail like LL Bean, as an example, my neighbor up the road here 45 minutes away, it's a very big tent there. While they do sell products for more extreme activities, they sell an awful lot of products that are just for general use. And they're very, very successful as a retailer. So again, if we're gonna spend all of our time looking down our noses at people who aren't as core as I am, I think that's a problem. But if we open up and say, hey, there's some business being done here and it's good business why wouldn't we get after it? One of the things you brought up was the hesitancy for the industry to sell their products in big box stores. Again, it probably feels like a conflict of, well, we can't we can't sell on a Target or a Walmart because that's not, you know, that's not special. That's not who we are. Is that a part of the opportunity as well that you see to reach beyond the specialty retailer? Absolutely. Now, look. I understand a lot of the product that the industry sells is very technical. You have to be trained in how to sell it. You have to be trained in how to use it in order for you to be happy with that. So not every product can go into a big self-serve retailer, but a kayak, sure, why not? Again, a fire pit, a pop -up shelter. I mean, I got to tell you Walmart sells a lot of pop-up shelters out there. So it’s wouldn't mean everything that the industry sells goes there, but I think there are an awful lot of products that could be there. And maybe it has to be sub-branded if you want to try to protect yourself there, although you're giving up some brand equity. If you've spent all your career or your lifetime of your brand building up the equity of that brand, and then you come up with a sub-brand that doesn't mean anything, you've given up some leverage there. Look, I think a lot of brands have figured out how they can be in more than one place. You look at, say, Nike and how many different kinds of retailers they sell their products to. And they've been successful in being able to segment that product around all those different channels. Yeah, and I don't know that they've diluted their brand equity as much as people might think they are, based on how diverse their product really is and all the corners of the world that it reaches. ‍ Cole Heilborn Do you feel like this downturn, is it healthy? Do you look at this as a good thing? ‍ Matt Powell Yeah, I do. Again, I think if you take the longer view, we really aren't in a downturn. We had it up and down, but we're still way above where we started. And I think, again, side effect of it, there are more people out recreating. The park visits are up, and the people spending time outside is going up. And it's probably weeded out some weak players and you never like to see anybody lose their business or lose their job. But you know, I think weeding out is always a good thing for the overall business. So in many ways, I think this has been healthy. ‍ Cole Heilborn As you look around, what questions are you asking yourself? Are there things that you're unsure about? Things that you're trying to answer these days? ‍ Matt Powell Well, I think, yes, I'm always trying to understand what's happening. And I challenge myself every day on the assumptions that I've made and the conclusions I've come to. I think you have to do that as an analyst. If you went outside, I got all the answers, and I don't need to learn anymore. You're out of business. So I'm constantly questioning myself. I don't know that I have a big thing that's troubling me, but I think I try to keep a very open mind about where I am and what I'm seeing. But look, we need freshness here. We need new ideas. We need new approaches. And in some cases, we've taken things as far as we can take them. We can't make shoes much lighter than they are today. We're not going to have any big breakthroughs there. We can't make a puffer jacket any lighter than it is. I mean incrementally lighter, yes, but breakthrough lighter, no. But you know, where's the pickleball of outdoors as an example, okay? What's the next big thing that people are going to gravitate to? We have some interesting things like Stanley Quentcher's that are having a moment right now, but I'm looking for more revolutionary kinds of things. Think about stand-up paddling and where it was, say, 15 years ago and where it is today and how that became a thing, going back even further with snowboarding when it first started up and how that just flipped the industry upside down. Mountains were saying, no snowboarders, only skiers, and all that silliness. But we need another big idea, I think more than anything right now to really reverse the soft spot that we're in. I know the core will always continue to cycle through new gear because people like the newest and latest thing. But has the industry become saturated? ‍ Cole Heilborn I think you mentioned at one point, our industry makes good product. It lasts a long time. It does its job. Have we just become saturated and that's part of this equation also? ‍ Matt Powell I think perhaps on the on the core side that we may be getting to the point of saturation. But on the family side, no way. There is so much more room there. So much more opportunity to, I think, to introduce consumers to being outside and other less strenuous outside activities, but nonetheless other activities. And, you know, this, I mean, one of the cool things about the outdoor industry is it's a bunch of gearheads, right? So, And even I think the family side, you know, whether, you know, the Yeti cooler run up that was so dramatic. You know, I think a lot of people who were not outdoorsmen bought Yeti coolers. And so, you know, can we do another version of that? Absolutely. So I know I think there's still a lot of run room here. ‍ Cole Heilborn Do you feel like our industry is short-sighted? Do we have a habit of not looking far enough into the future? ‍ Matt Powell Yeah, well, I think that is really impacting the entire sports industry. I think, first of all, the lead times are far too long. And so that you tend to get locked down in the process and maybe not looking ahead to the next thing. There are a lot of smaller, more entrepreneurial firms that are undercapitalized. Therefore, they have to be very careful about how they're allocating their resources, which holds us back. The bigger brands have all been really soft goods for the most part. Again, I don't know how much more innovation really can come in on the soft goods side. We certainly write fashion trends, but I don't know how we make a puffer lighter or a sneaker lighter or a boot lighter. ‍ Yeah, I think there's a certain inherent caution that has come into this industry as maybe risk -taking as the activities themselves are, the business has not been particularly ris -taking. ‍ Cole Heilborn What do you mean by that? ‍ Matt Powell Well, look, I mean people doing extreme things, they're doing dangerous things, rock climbing, solo hiking, and so forth. I mean, these are really dangerous activities that you have to have a lot of preparation a lot of courage for but then we get into the business side of things and I think people tend to be very conservative in their business practices not sure if we want to open up this retailer not sure if we want to go into this city not sure if we want to make things for the family and so I think that there's a tampening tampening down of that that that's holding us back as well. ‍ Cole Heilborn Why do you feel like that is because I'd almost I would assume that we would be a very risk calculated industry, we would know what risk to take and what to avoid. ‍ Matt Powell Yeah, you know, money does funny things to people. So, you know, I think when you're talking about my money, maybe I'm going to be a bit more conservative than I would be with somebody else's or even, or the courage that I have to tackle a really dangerous activity because I trust myself. I know what I can do and of course people make mistakes doing that as well, but I think there's a different thing when it comes to money. I think people just tend to be much more conservative there. ‍ Cole Heilborn Interesting. So to summarize, it sounds like there's a few different factors at play here that you think will help kind of right the ship or pull us out of this slump a little bit. And again, some of it sounds like it's just we're due for it based on the last few years. But to recap, it sounds like we just need to kind of ride the wave, ride it out, because it's here, it's going to be here. You just have to make things, you have to make it work. If we can find a new budding sport to kind of grow with and build upon, new product innovation, like how can the industry, how can we double down and continue to innovate? And then I guess maybe the biggest component is how can we get beyond ourselves. How can we get outside of the echo chamber and find others who don't look like us, don't act like us, who are different, but who still love getting outdoors in different ways. It sounds like that's kind of the three or four main points that you've summarized for us today. ‍ Matt Powell I think the only thing I would add is I think we need to de-risk the weather. I think we need to figure out or accept the fact that this is now the new normal, that we're not going to have cold and snowy winters. We're going to have warm and wet springs. ‍ And how do we respond to that? How do we reinvent ourselves around that? If 50% of the apparel business is outerwear and we're not gonna sell that much outerwear, how do we replace that? How do we find a spring business that can offset the loss of the winter business maybe as an idea? And so I think there needs to be a lot of thinking about how do I respond to my merchandising rather than just, I sold 5,000 jackets last year, I'm buying 5,000 jackets this year. And I'd rather figure out how do I transform this into something different, something new. ‍ Cole Heilborn Yeah, well, unfortunately, that's a topic that's bigger than any one of us to tackle, but nevertheless, something to be aware of and just observing. Matt, is there anything that we haven't discussed today that you'd like to leave our audience with? I appreciate your insight. I appreciate your perspective on some of this. Maybe one final question is, why does this matter for our audience? Why does this matter for our marketing industry? Well, look, ‍ Matt Powell I mean, I think the greatest thing about the outdoor industry is the passion of the people for the sport, for the activities that they do, for the environment, all of those things together, and people who figure out how to make a living and still supporting all of those things. And I think that's one of the great things about this industry is the passion of the people. And that's not going away. And I know I've been critical of some of the business practices perhaps, but never the passion. And I think that's one of the things that's kept this industry going. There are hardly any trade shows anymore. There are more than one trade show in the outdoor industry. And I think that speaks volume to the commitment of the community itself to want to preserve. And so I see that as a big, big plus. And again, I know I'm critical, but I'm also very in awe of the commitment of the people who are in the outdoor industry. ‍ Cole Heilborn Well, you can be critical and still want the best for everyone. Those two don't. They're not mutually exclusive. Exactly right. Matt, if folks want to find you, if they have further questions, if they want to learn a little bit more about what you're up to, where can people go to find you? ‍ Matt Powell Sure. Well, I'm on LinkedIn and I'm very active on LinkedIn. I repost a lot of stuff. I write a fair amount of things that are on there. So link me on LinkedIn. My email is matt@spurwinkriver.com And I'm easy to find. So reach out anytime. I'm always love talking and philosophizing about the industry. ‍ ‍", "token_estimate": 7958, "speakers": ["Matt Powell", "Cole Heilborn"], "start_timestamp": "00:00.27", "end_timestamp": "00:34.606", "podcast_index": 164, "episode_name": "EP 164: State of the Outdoor Economy", "slug": "ep-164-state-of-the-outdoor-economy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-164-state-of-the-outdoor-economy", "guest_name": "Matt Powell", "guest_title": "Advisor at Spurwink River", "categories": ["industry-trends"], "short_description": "In this episode, Matt Powell shares insights and observations about the economic state of the outdoor industry. It’s common news that the COVID boom then bust has spun the industry into a downward spiral but Matt sheds some new light into the predicament as well as opportunities that could break the industry out of its spiral.", "podcast_length": "44:18"}, {"id": "d070676e-d2c7-41aa-9b42-403ed946fa62", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 0, "content": "John Salzinger (00:00:02): I think we as consumers still can drive these corporations to advertise in a way that makes sense and change them dynamically fast, even faster than we can change our political system. And it is the advertisers responsibility to make sure the company survives. So if the survival is based on its consumer's morality, well that's a wonderful chicken in egg.\n\nCole Heilborn (00:00:27): Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Hey everyone, it's Cole here. I just want to do a quick introduction to this episode, but before I jump into the intro, I just wanted to say thank you. This is episode number 56, which means we've been doing this podcast for over a year now, and its success is because people listen to it. You listen to it. So I just want to say thank you. (00:01:20): If you want to be able to support the show in any way, you can head on over to Apple, leave us a review, five stars, one star, it doesn't really matter, or reach out to me. Find me on Instagram, LinkedIn. I'd love to know what the podcast means to you if there's ways that we can improve it. I don't typically do these introductions for each show. I believe that people want to hear from the guest, they don't want to hear from me, but I figured this episode could use a little bit of an introduction. It could use some context because we're going to just jump right in. John and I are going to jump right into this conversation without much setup, without much background. So here's your exposition. In this episode, I interviewed John Salinger. He is the founder of a company called Empowered. Empowered stands for Micropower Design, and most of you are probably familiar with them because of one of their products. (00:02:09): They're Lucy Light product, which is the inflatable solar powered little lantern. Empowered is on a mission to transform lives through thoughtfully designed clean technology. By utilizing innovative products, they're able to give people the power of self-reliance across the world. To date, they've been able to impact 3,800,000 lives and avert 2,400,000 pounds of CO2. As I got to know John, as we got to start speaking about what we could talk about on this show, it became really apparent that John's the type of guy who likes to think about big issues, and better yet, he can articulate his thoughts around those big issues. I don't know about you, but when I look around the world, I see trends that are concerning, excessive consumerism seems to be everywhere. Ads populate every inch of our lives, and it's understandable why we all love to get outside because we love getting away from the urban sprawl of advertising. You look at your phone, there's an ad, you go to your email, there's an ad, you walk down the road, you drive on the side of the road, and there's an ad. And it seems that advertisers are just constantly telling us to buy, buy, and buy. We never have enough. We never will have enough, but the only way to get closer to having enough is to keep buying. (00:03:33): Hundreds of millions of dollars are being spent on stuff that we don't need. I don't need the 10th pair of shoes that are currently sitting in my basement. I maybe want that 11th pair of shoes, but I certainly don't need them. And if anything, the outdoor industry, while we all love gear, we all love acquiring that next piece of gear n plus one exists for a reason. As marketers, I question our role in this excessive consumerism. I look at the impact of this excessive consumerism, the impact on the environment, the mental health impact of people who get wrapped up in possessions and get wrapped up in materialism. I look at the social media dilemma. There's the famous documentary out that we've done an episode on that talks about social media and the real dark, scary truths about what it is. And like it or not, we as marketers, fuel and pay for those services. That's what keeps the lights on. (00:04:41): I am not pointing any fingers and I'm making generalizations, but have we become so good at selling that we as a marketing industry are no longer concerned with the impact of what we're selling and how it comes across? I firmly believe that if there's any industry that can do better, it's the outdoor industry. I mean, that's why we're all here. We enjoy being progressive. We enjoy thinking about ways to get around obstacles to do things better, but I also know that it's really easy to pass the buck and find a reason to excuse the impact of what we do for a living. It's easy to say, well, marketers are just a reflection of society. We can't change society. Therefore, why should we consider how we market? And that's a fair argument and I don't have an answer to that, but these are the types of things that I wonder about. (00:05:28): And this is the reason why I wanted to do this introduction, because in this conversation you're about to hear with John, we dive into a variety of topics. I just kind of unload my questions on him around this kind of lofty, confusing topic about consumerism marketing and what role does marketing play in our country's excessive consumerism. If you enjoy this episode, again, feel free to leave us a review, reach out to myself or John. I'd love to know what you think. If you have any ideas around this conversation, around this topic that we didn't get into in this show, please let me know. I'd love to talk further with you because this is the type of stuff I really enjoy. I love these conversations. I love not knowing the answer to something and just wanting to learn more. So anyways, enough of my intro. Let's get right into today's episode. Welcome to the Backcountry Marketing Podcast. John, thanks for joining me today. How are you?", "token_estimate": 1564, "speakers": ["John Salzinger", "Cole Heilborn"], "start_timestamp": "00:00:02", "end_timestamp": "00:00:27", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}, {"id": "184eb90e-8bc9-4b51-b092-95b0a22b68fa", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 1, "content": "John Salzinger (00:06:28): I'm doing great. How are you?\n\nCole Heilborn (00:06:31): Fantastic. I'm super excited to chat today. I think we've got a very interesting topic. It sounds like a pretty lofty topic, so just for the sake of time, I'm excited to dive in and kind of start asking you questions and getting your feedback.\n\nJohn Salzinger (00:06:46): I'd love that. Thank you.\n\nCole Heilborn (00:06:48): So I don't know about you, but I look around our world and it just seems to be so saturated with ads. You look everywhere and you see an ad, and I mean, I use an ad blocker all the time to prevent ads from popping up. And it seems to have reached a point where it steals our time. Ads are manipulating us consciously, unconsciously, and you look at the impact that I feel like that advertising has on society. I look at the fast fashion industry, the turn and burn consumerism that our world is obsessed with, and I just wonder what are the impacts that that has on one, the environment, two on people's mental health? And I dunno, I look at that and I have tons of questions about the ethics of the advertising industry, and when I say ethics, I don't mean are we playing a PG 13 versus an R-rated commercial on tv, but I mean just kind of the whole state of the industry as a whole. So I guess I'm just curious to dive into that topic and learn more about your experience and your perspective around all of that.", "token_estimate": 356, "speakers": ["John Salzinger", "Cole Heilborn"], "start_timestamp": "00:06:28", "end_timestamp": "00:06:48", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}, {"id": "c7878d8b-fb1b-4be1-9c65-11f013162e45", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 2, "content": "John Salzinger (00:08:07): Yeah, so I'll try to take an approach that is personal to me that makes sense in terms of sort of a positive outcome at the end of it. What I say, sure, I guess I'll call it what you're describing is as sort of a mass materialism, there's sort of a digital targeted push. Now the advertising world has taken on and people are identified by their desires and don't necessarily, as a result, purchase their needs as much. They're distracted, so to speak. So it's sort of backwards. It's not like I'm hungry so I get food. It's more like, oh wow, this thing just hit me on Instagram and I'm going to buy it because it hit me on Instagram. But it's kind of like with any new technologies, I think marketing has just evolved, right? And there's an opportunity to use this sort of targeted approach in a socially conscious manner too, (00:09:17): In order to compete. It's important to know that we don't really market as companies to human beings anymore in terms of the pathway we're marketing to robots essentially algorithms, right? Amazon process it, how Google ads processes it, and then at the end of that whole road, it gets to a human, but you're actually advertising to a machine. So in a sense, I think Singularity has arrived in the marketing industry before any other, but I think it's important for corporations and companies to utilize the power of these tools responsibly and to solve problems and provide needs and information that's helpful to people's buying decisions versus misuse them and push whatever that company is just trying to get out of their inventory or trying to sell for the cheapest price, et cetera. So as opposed to just taking advantage of the technology, the technology itself is phenomenal and it can be used as power for good. (00:10:25): And so that's what we try to do at Empowered. So we tell our stories to those who we think are interested, but we also try to sell our products, which are solar in nature to not only those that are obviously on the east of the west coast of the US and will buy it, but we target individuals in emerging markets. We target people in middle America that might not be the first person to adopt solar, maybe based on price. And we think we make the world a better place that way, the environment a better place. And so as long as you understand the tool you're working with, I think it's okay and use it for good. But there is plenty who will inundate folks with everything that they think they like because they saw them search for it. And anything in excess, it can be problematic individually.", "token_estimate": 649, "speakers": ["John Salzinger"], "start_timestamp": "00:08:07", "end_timestamp": "00:08:07", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}, {"id": "5c54b7b5-721d-4618-bfdc-a623a22811e9", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 3, "content": "Cole Heilborn (00:11:25): And I think you made a good distinction there to preface this whole conversation. This isn't a advertising is bad episode, this is a, let's just think about maybe the ways that we're advertising and as you said, if you're doing it for good, that that's fantastic. One distinction you made there was the need versus the want. I guess how did we end up in this want society rather than this need focus? I feel like that's kind of a good foundation to start with.", "token_estimate": 122, "speakers": ["Cole Heilborn"], "start_timestamp": "00:11:25", "end_timestamp": "00:11:25", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}, {"id": "b8eaf745-9466-4374-88ce-d27ee9015769", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 4, "content": "John Salzinger (00:11:58): Yeah, this one's an easy answer for me. There's nothing here sort of hidden. This is a financial conversation. And I think the key fiber of our society unfortunately, is now synonymous to major corporations, ups and downs. So basically the stock market, the price that every large corporation with massive market share post daily is what drives this, this conversation. And in essence, our morality, not because you and I feel a certain way, but that's being thrown at us. And the reasons behind why it's being thrown at us is to change a stock price. So I think it's imperative, right? For startups, entrepreneurs, new companies, example, clean energy companies like Empowered that are B Corps or for purpose or trying to solve a problem or solve a human need, just a company that's trying to solve a need, spend as much of that marketing on mission, awareness on product awareness, but also on brand and why you're doing what you're doing versus I'm just going to do this because it's going to make me money. (00:13:18): To answer your question, it's important to solve human needs. And so there's an opportunity to educate and using your platform to do so is essential because there's a lot of media out there that's not necessarily educating, and even our education system is kind of broken. And so we're kind of in a situation where we really need to think about we as business folk and what the messaging we put out, are we making our planet and our people better by what we put it out by what we put out? Or are we making it worse? Are we taking actually the easiest path to market, which is marketing products that people need and can solve problems and aren't harming or hurting the planet or people? Or are we simply just trying to look at our tools again and use them for whatever it is that will make us the most money in the shortest amount of time? And I think there's a responsibility to all of us individually, but as business owners to utilize this sort of time when it's needed to help our planet and to help our fellow people around the world. I mean, I'm lucky I'm in Brooklyn, I'm okay, I'm fine, but there's a lot of people that aren't and the planet's not fine. And I think this is a chance for the private sector to step up. I hope that answers the question.", "token_estimate": 578, "speakers": ["John Salzinger"], "start_timestamp": "00:11:58", "end_timestamp": "00:11:58", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}, {"id": "aea168de-25c1-4ef6-bd87-1ed446c308ec", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 5, "content": "Cole Heilborn (00:15:02): No, that's good. Yeah, no, that was a great response. So I guess, but let's take it farther back. In doing some research, it sounds like pre-World War ii, the average consumer bought based on what they needed, they were pretty frugal. They identified the things in their life that would help them, and they would only purchase those things in a general sense after World War ii. There's some interesting things that motivated this, but our society shifted to a want based society where we looked at things and said, I don't need that, but I'm going to buy it anyways. I'm going to buy that third pair of shoes and wear them 20 days out of the year. What motivated that change?", "token_estimate": 176, "speakers": ["Cole Heilborn"], "start_timestamp": "00:15:02", "end_timestamp": "00:15:02", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}, {"id": "89cec675-f85f-4304-a6dd-d7f5ed960bfb", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 6, "content": "John Salzinger (00:15:45): Yeah, well, so you and I have secretly had another conversation before. I mean, there's a great movie that I recommend to any marketer, anyone who's starting a company. It's called Century of Self. And basically it has a few parts, but the first part really focuses on taking wartime propaganda where you're taking information to the masses for a specific sort of lens that you're trying to push on people and turning it into public relations. And it's built in Sigmund Freud's studies, whatever you feel about all of his studies and what they embody. But it's interesting, and there are examples of this where there was a parade in New York. It was a holiday, it was after the war, world War ii, and a bunch of debutantes made it to where the press was hiked up their skirts a little, therefore showed a little bit of the sexual nature of advertising that seems to work well, working on human innate urges. (00:16:58): They took out cigarettes from sort of their pseudo garter belts in front of the press and lit them at this perfect moment where all the press was there, the parade had stopped, and it was this shock value that these women were doing this, but that they were also lighting a cigarette because before this, women did not smoke. It was thought of as a male sort of product when they were interviewed because the press was right there. So this was the physical equivalent to digital targeted advertising. The press asked them, what are you doing? And they said, well, we're smoking the torture of freedom. (00:17:42): So nationalism, they used sex, they used all of these different kind of macro ideologies in sociological thoughts across society, and in a sense took advantage of them. And literally within months, I mean this movie's phenomenal. Within months, the other half of the United States was smoking cigarettes. Women were smoking cigarettes. That's a good example of what I would say don't do. I mean cigarettes, were also put next to the candy for years and still are sometimes in plenty of stores and try to market to kids. There's a responsibility here, and humans have always had these tools. That's what we've been talking about. It's about not misusing 'em everything in moderation. I mean, look, there is an element of personal responsibility, life balance, right? It's crucial to happiness. So I don't like to just deconstruct things into something that's not complex and give an answer. The food we eat, the medicine we're prescribed, the environment we live, the education we receive, the access to choices and the inequality built into our systems and these pillars, that's really important to the key understanding in your state of mind. (00:19:06): So in moving that into advertising and small businesses, et cetera, pricing your products, offering something that has equity involved that people can enjoy it at different economic status, I think is important. Happiness is tough and the industry has a role to play, but I don't think it's alone, right? In a sense, it's a mirror of who we are, and now it's more so than ever. It's kind of a back and forth mirror. So if I Google something and you Google the same thing because of the targeted nature and our cookies in our servers, our IP addresses, we're going to have different results that's really kind of scary and interesting.", "token_estimate": 838, "speakers": ["John Salzinger"], "start_timestamp": "00:15:45", "end_timestamp": "00:15:45", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}, {"id": "1aa818a4-2e34-40bd-84bb-2bd1010d2b8b", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 7, "content": "Cole Heilborn (00:19:55): So that, that's a good point. Some would say they look at the consumer behavior and they say, well, as advertisers we're just reflecting and giving the consumer what they want. But at the same time, as you said, it's a mirror, it's a two-way street, and there's give and take on both sides of that balance of responsibility. Is there a way to quantify what type of responsibility the advertiser has in that dialogue between the consumer?\n\nJohn Salzinger (00:20:26): Yeah, I mean, because we're so targeted, because terms and conditions are just, no one reads them, everyone clicks them. There's a little bit of a game going on where people can become exploited. (00:20:43): This is a good time. So we're January, we just had a pretty hostile election cycle. We've had a tough time in the country. In my opinion, people in planet were put last, more so now than ever before politically. And I think the private sector in general has that choice to solve problems and do good or enable poor choices and cause harm. And I think best practices and fairness and advocacy, speaking truth to power, standing up for the greater good is clearly not represented today by what I guess has been called laughably. Public servants, well lobbied generally. There's been tons of studies. They don't really do what the public wants, therefore a capitalist society. Marketing is a huge component. And then there's a fundamental responsibility to cause social and environmental progress and change. Empower does amicus briefs. We use social to post about all sorts of fairness issues. (00:22:03): We think that there's a key responsibility in the private sector to be, I guess you'd call 'em private servants. Now there's a void, right in what our government is doing for us as a collective self. At the end of the day, your vote counts right politically, but your dollars, you spend count. And so you can choose wisely. And when I say wisely, I don't mean the most intelligent choice ever. I'm just saying basically in the way you should be voting, which I don't believe everyone does at this point, partially because of media and politics and the ads that are served. But are you spending your dollars in products and companies that serve your self-interests, that serve the greater goods, self-interest that serve the community, self-interests, the environment, self-interests? That's kind of really important, right? Empowered, we're a benefit corp and a B corporation, so we have to do that. We're held accountable to do that. We've impacted 4 million lives, right? We've averted 2.8 million tons of CO2, and we talk about that constantly because we want other companies to emulate that and realize that's a choice. That's a choice we made. We're a successful company. And you too, as a company can do that, or you too as a consumer or a corporation can get involved with our mission and make change. (00:23:31): But I think that responsibility falls on everyone, and especially now because the public sector, in my opinion, is failing us miserably in terms of our own self-interest and wellbeing.", "token_estimate": 778, "speakers": ["Cole Heilborn", "John Salzinger"], "start_timestamp": "00:19:55", "end_timestamp": "00:20:26", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}, {"id": "6db49558-470d-42da-892e-3213b5c8a8f4", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 8, "content": "Cole Heilborn (00:23:43): Do you feel like that's why we're seeing such a push towards the private sector in terms of supporting brands that are doing good air quotes?\n\nJohn Salzinger (00:23:54): Yeah. I mean, Unilever is a B Corp, right? Can you imagine? Right? Yeah, absolutely. Patagonia has done very well. I mean, it's important. I think this has become, I guess, the most participatory democracy, although it's been scary that I've ever seen in my lifetime. And people can have all sorts of opinions on all sides of the spectrum, but we've never seen so many people get out there and vote or get out there. And I'll just talk about peaceful protests at this point because anything beyond that doesn't work for me. But I do think that yes, a hundred percent, I think in life personally, and then societally, there's never a straight upward slope. It's always there's dips on that and you're lucky if those dips are just small dips. But I think this is a dip. I think it's a reaction to some bad practices for people, planet. And I think what's really cool about it in a corporate structure is it becomes an opportunity because if you're quiet as a company right now, most people aren't happy with that. So you do have to take a stand and when dollars and revenue and profit align with doing good and purpose, because consumers force it to, so this is the modern day boycott, except it's the opposite. You're choosing where to put your money, and by doing that, you are boycotting companies that aren't doing good. It's not called a boycott, but I think essentially it's\n\nCole Heilborn (00:25:45): Interesting. Do you feel like there's more, if you were to, I don't know, if you're looking at the amount of power that the average consumer has over the powers that be, is it more valuable to put your money where you want to see change or put your vote, I guess, does one have more power over the other?", "token_estimate": 477, "speakers": ["Cole Heilborn", "John Salzinger"], "start_timestamp": "00:23:43", "end_timestamp": "00:25:45", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}, {"id": "e8762a5f-3f42-4b47-8256-9f004250f648", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 9, "content": "John Salzinger (00:26:07): Well, I mean, we could get into a long debate about the electoral college right here in the state, but we won't. Sure won't. Your vote matters. Your vote counts. I don't want to ever dissuade anyone. People have fought for years. There's countries where no one votes, not enough people vote here. If everyone voted here, if people even voted on their economic interests here versus on all these social constructs, gender, race, whatever the newest distraction is. In other words, if all the people that were lower income or middle class voted as a block in their own, well then Congress, all the branches of government would absolutely do the people's bidding or they wouldn't get reelected. Now it doesn't happen, but the more you vote, the more people you can get to vote, the more people that vote, I think we're at under 50% still, even though it was a big year, the better off we are. (00:27:06): And so please vote. And then also please look into where you put your money. So whether you have expendable income and you're putting it into stocks, or if you're simply a customer, consumer buying product, that means everything. And I think in a capitalist society, definitely vote because we're supposed to be a democracy on some level. We're not supposed to be this sort of oligarchy of 1%, which is sort of grown out of people taking advantage. Those in power, taking advantage, I think it's incredibly important to understand your personal power, and the power is in both sides of the spectrum, but in a capitalist society that's not as much. It's more capitalism than it is democracy. Your dollar means everything because if that stock goes down, something's changing. And you did that, and if you bought something from a good company and then you shared it on social and you got other people to do that, or you pointed out that another company wasn't doing something that was right and you shared that to your friends, you can have an enormous impact. (00:28:20): I'll just add lastly, if you stay quiet, then it's your own fault. None of this is simple, but we're all part of it. We're all part of the problem, and we all can be part of the solution. I think if anything, now's the time to, it's not just speak up, but it's be an activist, it's do the right thing and then talk about that. Show those we are a for-profit C corp that makes money and we impact people and profit and excuse me, people and planet in enormous amounts, we're only 14 people. And so to impact 4 million, that's a lot. Not everyone is in a position to do that initially, but everyone is in a position to add pressure to a company through your financial choices of which you're buying. It's a great question. I hope people do it. I hope people take the time. People take the time to look up, is the product good? What are the reviews? There's a lot of platforms done. Good is an example. B Corp is another example. These are great platforms that tell you what companies are good and what aren't. I mean, done good, my goodness, they have a Chrome plugin that literally when you Google will tell you what companies are good and what aren't. It's so easy these days. Right?", "token_estimate": 796, "speakers": ["John Salzinger"], "start_timestamp": "00:26:07", "end_timestamp": "00:26:07", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}, {"id": "848b622f-89c5-4ef0-8df0-33142d7e1d65", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 10, "content": "Cole Heilborn (00:29:47): Yeah. Interesting. So thinking about, I guess, again, kind of coming back to one of my original points and just curiosities, you see the impact that companies who maybe aren't focused on doing good are having on the average consumer's mental health, obviously the climate impact and the consumerism cycle, what role does advertising play in that? Does that perpetuate, is it responsible? Is it the user's responsibility, the consumer's responsibility to try to negate those things? Yeah, I dunno.", "token_estimate": 131, "speakers": ["Cole Heilborn"], "start_timestamp": "00:29:47", "end_timestamp": "00:29:47", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}, {"id": "8dbbf15b-3cdd-4bd0-a46d-ca1d0b8ce980", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 11, "content": "John Salzinger (00:30:33): Yeah, I mean it's both, but I think it's cool cycle. It's not quite chicken and egg. The consumer decides also in this case, the government did a good job, right? There was a lot of research on cigarettes as an example. I know this has been half the conversation I smoked for 10 years like a knucklehead, but I haven't for 30 cigarettes are kind of a good situation because they were marketed as something without any warnings and then warnings were put on them and cigarette companies have been forced into other industries or they wouldn't have survived. Now you can talk about their practices and food, et cetera. It may not be the best, but they've been forced out of this one industry that literally will choose how you die. (00:31:24): And so I think it's a really glaring good example on that negative side of things. On the positive side of things, there's so many wonderful companies, not only empowered our company, but Caine in water filters, Patagonia in retail, there's so many different companies that are doing such good things. A lot of people like to look at Amazon and simplify and say, oh, they're this big behemoth. They're doing so many horrible things. We work with Amazon Disaster Relief, which is another department of Amazon that literally gives money for logistics for product to natural disasters all over the world and work with them to get thousands and thousands of our products to hundreds of hurricanes and wildfires. So I think we as consumers still can drive these corporations to advertise in a way that makes sense and change them dynamically fast, even faster than we can change our political system. And it is the advertiser's responsibility to make sure the company survives. So if the survival is based on its consumer's morality, well that's a wonderful chicken and egg.\n\nCole Heilborn (00:32:43): So what is advertising done in your perspective?", "token_estimate": 479, "speakers": ["John Salzinger", "Cole Heilborn"], "start_timestamp": "00:30:33", "end_timestamp": "00:32:43", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}, {"id": "f2282305-af01-46ef-90d8-26d693e00562", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 12, "content": "John Salzinger (00:32:49): So moving away from public service announcements, I think when I was growing up, I mean they were funny, they were cool. They were like, give a hoot, don't pollute. They were like the egg in the frying pan, this is your brain on drugs used to just make me hungry. Those kind of things were like, they were useless in a sense. They were just PR initiatives. And now there's a ton of cause marketing, and we've worked with Direct Energy, we've worked with Creas Energy, we've worked with Citizen Watch, we've worked with Osprey, and we've worked with so many companies in order to change, to change what those companies are doing. And it's true cause marketing. So they are actually doing what they say they're doing. And you can take the biggest companies in the world that are really hard to move, and in our case, we give them a turnkey kind of Toms model where they can offer a product to their consumer. (00:33:56): One of our products, so Citizen Watch, I'll use that as an example, when they sell their eco watch, which is driven by light, so it makes sense that they would send another one of our products that's branded with a nice watch face on the top of our Lucy Light, Lucy Solar Light to their product, excuse me, to their consumer. And that consumer also has a note on that product that says, on your behalf, citizen Watch is funding an empowered light to one of 700 NGOs they work with for someone who needs it. Now that's being done and it's having a great impact on us on the NGO that's putting it out there on the media, that's covering it on the whole awareness. But why is it happening? It's happening because the loyalty of that brand went up 20% and their stock price went up. So instead of just hating capitalism, understand the tracks you're on and drive the appropriate train up those tracks and make change, and that's what we do. (00:34:58): And so I think it's an opportunity. All of this stuff, all of these problems, everything is an opportunity in disguise. Everything outside of something like mortality, you can resolve, but you got to work at it, you got to think it through. But what a great time for companies to feel like they need to make a difference and consumers and the population holds 'em to account. If you do something that's disingenuous or inauthentic, you'll get caught out there and that'll be the worst CSR corporate social responsibility campaign that you've ever done. So I think it's been fantastic what's happening in the private sector, and I think it's a shared responsibility again.", "token_estimate": 642, "speakers": ["John Salzinger"], "start_timestamp": "00:32:49", "end_timestamp": "00:32:49", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}, {"id": "86ed20c3-9248-42b9-9bc3-f645ea326318", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 13, "content": "Cole Heilborn (00:35:44): Yeah, that's an interesting point. I know a lot of people, I don't know them personally, but I just know a lot of people look at the capitalistic model and they see it for all the negative things that come out of it. But you brought up a good point is that if you know how it works, you can use it for good or bad. In what ways does capitalism open up opportunities for other types of good outcomes, other types of cause marketing, other types of businesses to rise and do work for good?", "token_estimate": 129, "speakers": ["Cole Heilborn"], "start_timestamp": "00:35:44", "end_timestamp": "00:35:44", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}, {"id": "04318bbd-3245-4e2f-91d8-a3ebf53d05de", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 14, "content": "John Salzinger (00:36:24): Yeah, I mean I think it's still a challenge, right? Because the one driver of capitalism is growth and the one driver of that is the stock market. And so you have to fit into that model. There's a lot of companies that make a ton of money and do a lot of giving, but they may do that giving for tax breaks. Same with individuals. I think one of the biggest issues, I don't have the answer to this particular question, but I can say that one of the challenges is the inequality that we face today, both in private citizens and sort of 1% of the money going to a few people who decide where it should go and how much should go, but they still have a billion dollars or more. If there's 99, I mean, this is a good example. If there's 99 burgers in a room or a restaurant, or excuse me, a hundred burgers and a hundred people, one person has 99 of them, that's not okay, even if they give a little scrap here and there to everyone else. (00:37:30): So capitalism, where we are today is not in a great position for the good of all. I will say we can continue to drive that into situations with accredited organizations, checking practices, et cetera. But again, it ends up with the consumer. It doesn't end up with the corporation, nothing changes from the top down. The status quo is not going to change a thing right now. It's great for the status quo, it's great for those who own the means of production today. However, we can change that. We can do real fundamental change. And sort of getting back to your question, I just think that it's essential, right? It's completely essential that we as people drive the movement, drive the corporations to do good. And when a corporation funds an entrepreneur because it's something that they can talk about, maybe this corporation, an impact fund, or maybe these investors have impact investment because it's sexy these days or it draws more attention to their fund. (00:38:45): That's a good way that capitalism can be used. That said, it has to be authentic, it has to be real, it has to be patient. So there are a lot of vehicles out there that there's a ton of foundations. The fundamental question to that is that good because that is a capitalist structure, but not an Adam Smith capitalism. That's a capitalist structure that's built with all these inequities. So that capitalist structure is being forced by people to decide, okay, we got to do some good. Is that the perfect structure? Yeah. Capitalism is what we've found in my lifetime. Half a century I'm dating myself is it's perfect as long as it gets bailed out by socialism every 10 years. So I think there are real problems right now, and I think that the only way to change that and force those corporations and advertisers to do what's right and it's happening, what's why CSR has sort of been invented, nonprofits, excuse me, for-profits have been invented, B Corp and benefit corporations have been invented, social capital has been invented, but we got to keep pushing. It's on you and me and it's every single person to push these corporations to do more. They're not going to do it alone. So yes, I'm positive about the direction we're not there. We need more people to fundamentally understand why things work the way they do in this capitalist version and make the corporations do more and share some of the burgers.", "token_estimate": 841, "speakers": ["John Salzinger"], "start_timestamp": "00:36:24", "end_timestamp": "00:36:24", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}, {"id": "a05c9ff6-6c00-478b-a11e-49f3ea9e4494", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 15, "content": "Cole Heilborn (00:40:31): So if we're able to push the corporations to do more, do you care why they're doing it? Because I guess I see two options. The public pushes the corporation to share more burgers or give out more burgers, but one, they're doing it because they generally believe it's the right thing to do, or two, they're doing it because it offers tax incentives or they're doing it because that's what the consumer wants them to do. Does that why portion matter?\n\nJohn Salzinger (00:41:03): Yeah. Yes and no. So first they should give out stoves, right? So make burgers today. Right now we'll work with almost any corporation with a few excluded. I'll mention cigarette companies again, because an easy target, we'll work with almost anyone in order to fund good. So the why in the immediate doesn't matter as much, but in the long term, the why is everything, and that's how you come to a long-term solution. But if you are able to get enough people where they are positioned in a fair and equitable manner to do good for themselves and their community, that will write itself and the why won't matter as much. Unfortunately. Now, the why is built into systemic challenges across all sorts of issues that we've seen come to bear this year.\n\nCole Heilborn (00:42:10): But how do you do that? Because how do you change why that's generated by their perspective on life, their experiences, their values, their morals? That's not an easy thing to do.", "token_estimate": 365, "speakers": ["Cole Heilborn", "John Salzinger"], "start_timestamp": "00:40:31", "end_timestamp": "00:42:10", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}, {"id": "8c885d8f-9a24-4f56-bdbf-c35227a0c4b8", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 16, "content": "John Salzinger (00:42:26): How do you get people that have too much in power to change? Is that sort of the question? I guess so. I don't know, maybe, right? So I'd take it as such. I think it takes time, it takes pressure, it takes public policy. I think there's been a ton of deregulation that's hurt. The average person. I think there needs to be regulation. I think there needs to be fairness. I think there needs to be the laws that are in place on monopolies need to take into effect. I think HR has unfortunately taken the place of unions that had teeth and HR doesn't. You go to HR in a big corporation and they just sort of pet you and say, everything's okay, don't worry. I just think this is a time and place. It's unique. (00:43:19): This is an opportunity. I don't want to make this sound dire all the time. I think can change the hearts and souls of people in the biggest corporations because with empowered, we do. We've worked with Morgan Stanley, we've worked with some of the biggest corporations in the world, and it makes a difference to the people. When we sell to Walmart or REI, we're in REI in Walmart because they like our products because we can charge phones, because we can illuminate your campground in a solar clean way. But you know what? They like our mission. They like to share our mission. They like to go home and tell their kid they're working with a company that is helping the world, helping the environment. It's about winning the hearts and minds. It's about educating people so that they know what is right and wrong and that there's, you do something and there's a cause and effect. (00:44:20): So education, morality, logic, and then execution and activism. And we can do that. It's happening now. It's scary because it's happening on every front in all different directions, but this is an opportunity now an opportunity for the everyday consumer to take advertisers and thus companies and their governments to task and voice their opinions and their buying choices and their voting choices and what channel they watch. Frankly, and there's been a lot of that. There's been protests when a company does the wrong thing and the Isaac and consumer and changes immediately. I think Uber supported Trump at a time when he was had, in my opinion, an awful immigration policy bar. Barrack and Uber almost went out of business. So they changed quickly. Their CEO is gone. Boom. So again, there's a lot of these opportunities and examples in just the last few years. We can't take our foot off the pedal. We as people just because something's not in the media cycle. We can't assume the systemic issues, racism, et cetera, here in the US and around the world, frankly are not going away because somebody didn't get killed this week that didn't get covered on the news. So it's very important to understand that we're consistent in what we do and we have choices. And so I think it's important to exercise your choices in life on what you do.", "token_estimate": 745, "speakers": ["John Salzinger"], "start_timestamp": "00:42:26", "end_timestamp": "00:42:26", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}, {"id": "3488bb82-b5f7-44db-913e-1eb28973da2b", "episode_id": "fde769da-fa02-42e1-88b0-86f7ca00aa72", "cms_item_id": "68225dfc7bb476527f8c4863", "chunk_index": 17, "content": "Cole Heilborn (00:45:56): So that's kind of a good segue because I'm curious to hear your perspective on the idea that advertisers, we design our ads, we design our contents to engage with people, and sometimes that engagement reaches a place where we're just trying, we're trying to win their time, we're trying to get them to look at our thing longer. And yes, every consumer has a choice. If they're going to, for example, click the skip ad on YouTube or not. But advertisers like we've become so good at understanding human emotions, human desires, what triggers us that we are almost kind of hacking people's subconscious and using that to our advantage. Is that a problem? Using it for good or bad?", "token_estimate": 176, "speakers": ["Cole Heilborn"], "start_timestamp": "00:45:56", "end_timestamp": "00:45:56", "podcast_index": 56, "episode_name": "EP 56: John Salzinger | The Advertisers Responsibility | MPOWERD", "slug": "ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "web_url": "https://www.portsidepro.com/podcast-feed/ep-56-john-salzinger-the-advertisers-responsibility-mpowerd", "guest_name": "John Salzinger", "guest_title": "Founder of MPOWERD", "categories": [], "short_description": "Toxic consumerism, advertising and the marketer's responsibility", "podcast_length": "1:20:40"}]
